1	using GA;
2	using System;
3	using System.Collections.Generic;
4	using System.IO;
5	using System.Linq;
6	using System.Reflection;
7	using TGL;
8	
9	namespace RubikCube
10	{
11	    // GPU compute pipeline for the genetic algorithm: shader programs, SSBO/UBO buffers and the GA
12	    // loop. Everything is static and shared - it belongs to no particular render window (TGLContext).
13	    // Init() must be called once while a GL context is current (TGLContext.Create does that).
14	    public static unsafe class Gpu
15	    {
16	        public static uint InitProgram, EvaluateMicroProgram, EvaluateMacroProgram, SortProgram, SelCrossoverProgram;
17	        public static Ssbo Population, Children;   // parents (binding 0) / crossover output (binding 1); ping-ponged in ExecuteGA
18	        public static Ssbo CubiesBuffer, FreeMovesBuffer, SolvedBuffer, ActiveBuffer, PlanesBuffer, SeedMovesBuffer;
19	        static string Setup, Variables;
20	        static int CompiledN, CompiledSize;
21	        static uint NumSeeds;   // specimens pre-seeded by Init (host-built SeedMoves)
22	        public static int GenerationsCount;
23	
24	        // --- Instanced cube render (Gpu owns the GL resources; TGLContext gathers the scene). ---
25	        // All cubies share ONE base hypercube mesh (TCubie.Cube), differing only by their transform,
26	        // so we upload the mesh once and draw each cubie as an instance fed its ND world matrix.
27	        public static uint RenderProgram;
28	        static uint renderVs, renderFs, cubeVao, attrBuf, idxBuf;
29	        static int cubeIndexCount;
30	        public static Ssbo PosBuffer, XformBuffer;   // bindings 8 / 9, right after the GA's 0-7
31	        static float[] xformScratch;
32	
33	
34	        // One-time GPU setup: reserve the buffers, create the program + shader objects (attached but
35	        // not yet compiled), then compile them for the current cube. Call once with a current GL context.
36	        public static void Init()
37	        {
38	            Variables = ReadManifestText("Resources.Variables.glsl.c");
39	            Variables = Variables.Replace("#define uint unsigned int", "");
40	            Setup = ReadManifestText("Resources.Setup.glsl.c");
41	
42	            // Reserve the buffers once, in binding order (0..7 as declared in Setup.glsl.c). The
43	            // constructor only reserves id + binding; CreateBuffers sizes and fills them per run via Update.
44	            Ssbo.ResetBinding();
45	            Population = new Ssbo();                                // 0
46	            Children   = new Ssbo();                                // 1
47	            CubiesBuffer    = new Ssbo();                           // 2
48	            FreeMovesBuffer = new Ssbo();                           // 3
49	            SolvedBuffer    = new Ssbo();                           // 4
50	            ActiveBuffer    = new Ssbo();                           // 5
51	            PlanesBuffer    = new Ssbo(OpenGL.GL_UNIFORM_BUFFER);   // 6  std140 UBO
52	            SeedMovesBuffer = new Ssbo();                           // 7  Init seed sequences
53	            PosBuffer   = new Ssbo();                               // 8  base ND vertex positions (render)
54	            XformBuffer = new Ssbo();                               // 9  per-instance ND world matrices (render)
55	
56	            // Create the program + shader objects once and attach them. BuildShaders only (re)sources,
57	            // compiles and links these same objects, so nothing is ever created or deleted again.
58	            InitProgram = CreateComputeProgram();
59	            EvaluateMicroProgram = CreateComputeProgram();
60	            EvaluateMacroProgram = CreateComputeProgram();
61	            SortProgram = CreateComputeProgram();
62	            SelCrossoverProgram = CreateComputeProgram();
63	
64	            // Render program is VS+FS (not compute), so create/attach both shaders here; BuildShaders
65	            // sources and compiles them (with N injected) alongside the compute programs.
66	            RenderProgram = CreateRenderProgram();
67	
68	            BuildShaders();
69	        }
70	
71	        static int GetDefineValue(string defineName)
72	        {
73	            string targetToken = "#define " + defineName;
74	            using var reader = new StringReader(Variables);
75	            string line;
76	            while ((line = reader.ReadLine()) != null)
77	            {
78	                line = line.Trim();
79	                if (line.StartsWith(targetToken, StringComparison.Ordinal))
80	                {
81	                    string valuePart = line.Substring(targetToken.Length).Trim();
82	                    if (int.TryParse(valuePart, out int result))
83	                        return result;
84	                }
85	            }
86	            return -1;
87	        }
88	
89	        static void SetDefineValue(string defineName, int value)
90	        {
91	            var oldValue = GetDefineValue(defineName);
92	            var defineLine = "#define " + defineName + " ";
93	            Variables = Variables.Replace(defineLine + oldValue, defineLine + value);
94	        }
95	
96	        // Injects N/SIZE from the current cube as compile-time defines (the shader arrays are sized by
97	        // them) and (re)compiles + links the existing programs so they match the cube. Called from Init
98	        // and again by CreateBuffers whenever N/SIZE change. Population / genes / generations stay as
99	        // authored in Setup.glsl.c.
100	        public static void BuildShaders()
101	        {
102	            SetDefineValue("N", TAffine.N);
103	            SetDefineValue("SIZE", TRubikCube.Size);
104	            SetDefineValue("CUBIES_COUNT", (int)Math.Pow(TRubikCube.Size, TAffine.N));
105	            TChromosome.GenesLength = GetDefineValue("GENES_COUNT");
106	            TGA<TRubikGenome>.PopulationCount = GetDefineValue("POPULATION_COUNT");
107	            TGA<TRubikGenome>.GenerationsCount = GetDefineValue("GENERATIONS_COUNT");
108	            TGA<TRubikGenome>.StallLimit = GetDefineValue("STALL_LIMIT");
109	            CompiledN = TAffine.N;
110	            CompiledSize = TRubikCube.Size;
111	            noOpPenalty = float.NaN;
112	
113	            CompileComputeProgram(InitProgram, "Resources.Init.glsl.c");
114	            CompileComputeProgram(EvaluateMicroProgram, "Resources.EvaluateMicro.glsl.c");
115	            CompileComputeProgram(EvaluateMacroProgram, "Resources.EvaluateMacro.glsl.c");
116	            CompileComputeProgram(SortProgram, "Resources.Sort.glsl.c");
117	            CompileComputeProgram(SelCrossoverProgram, "Resources.SelCrossover.glsl.c");
118	
119	            // Render program (VS+FS) + base mesh - same rebuild path as the GA on N/SIZE change.
120	            CompileRenderProgram();
121	            BuildCubeMesh();
122	        }
123	
124	        static string ReadManifestText(string dotPath)
125	        {
126	            var assembly = Assembly.GetExecutingAssembly();
127	            string rootNamespace = assembly.GetName().Name;
128	            string resourceName = $"{rootNamespace}.{dotPath}";
129	            using Stream stream = assembly.GetManifestResourceStream(resourceName);
130	            using StreamReader reader = new StreamReader(stream);
131	            return reader.ReadToEnd();
132	        }
133	
134	        // Create a compute program and its shader and attach them (once, in Init). Sourcing, compiling
135	        // and linking happen later in BuildShaders, so an N/SIZE change just recompiles these objects.
136	        static uint CreateComputeProgram()
137	        {
138	            var program = OpenGL.CreateProgram();
139	            var shader = OpenGL.CreateShader(OpenGL.GL_COMPUTE_SHADER);
140	            OpenGL.AttachShader(program, shader);
141	            return program;
142	        }
143	        static uint CreateRenderProgram()
144	        {
145	            var program = OpenGL.CreateProgram();
146	            renderVs = OpenGL.CreateShader(OpenGL.GL_VERTEX_SHADER);
147	            renderFs = OpenGL.CreateShader(OpenGL.GL_FRAGMENT_SHADER);
148	            OpenGL.AttachShader(program, renderVs);
149	            OpenGL.AttachShader(program, renderFs);
150	            uint rid;
151	            OpenGL.GenVertexArrays(1, &rid); cubeVao = rid;
152	            OpenGL.GenBuffers(1, &rid); attrBuf = rid;
153	            OpenGL.GenBuffers(1, &rid); idxBuf = rid;
154	            return program;
155	        }
156	
157	        // (Re)source the program's single attached shader with the current Setup header, compile it and
158	        // relink. The objects already exist (created in Init); the shader handle is read back with
159	        // glGetAttachedShaders rather than cached, so the class keeps only the program handles.
160	        static void CompileComputeProgram(uint program, string dotPath)
161	        {
162	            uint shader;
163	            int count;
164	            OpenGL.GetAttachedShaders(program, 1, &count, &shader);
165	            var setup = Setup;
166	            setup = setup.Replace("#include \"Variables.glsl.c\"", Variables);
167	            var code = ReadManifestText(dotPath).Replace("#include \"Setup.glsl.c\"", setup);
168	            OpenGL.CompileShader(shader, code);
169	            OpenGL.LinkProgram(program);
170	        }
171	
172	        // Uploads the per-run data into the buffers reserved in Init (0 Population, 1 NewPopulation,
173	        // 2 Cubies, 3 FreeMoves, 4 SolvedCubies, 5 ActiveCubies, 6 Planes UBO). Update reuses the same
174	        // ids/bindings and resizes the store as needed, so there is no buffer churn between GA runs.
175	        public static void CreateBuffers(TRubikCube cube)
176	        {
177	            // Keep the shader in sync with the cube: N/SIZE are compile-time defines, so recompile
178	            // when the dimension or size changed, otherwise the shader reads Cubies out of bounds.
179	            if (CompiledN != TAffine.N || CompiledSize != TRubikCube.Size)
180	                BuildShaders();         
181	            var populationSize = TGA<TRubikGenome>.PopulationCount * (TChromosome.GenesLength + 2) * sizeof(int);
182	            var cubies = cube.PackCubies();
183	            // Pad empty index arrays to one element so we never make a zero-size SSBO (unreliable
184	            // .length() / binding). The countSolved / countActive uniforms gate the loops.
185	            var solved = cube.SolvedCubies.Select(c => c.StartIndex).ToArray();
186	            if (solved.Length == 0) solved = new int[1];
187	            var active = cube.ActiveCluster.Select(c => c.StartIndex).ToArray();
188	            if (active.Length == 0) active = new int[1];
189	            // std140 array of ivec2: each element is padded to 16 bytes (vec4 alignment).
190	            var planes = new int[TAffine.Planes.Length * 4];
191	            for (int i = 0; i < TAffine.Planes.Length; i++)
192	            {
193	                planes[4 * i] = TAffine.Planes[i][0];
194	                planes[4 * i + 1] = TAffine.Planes[i][1];
195	            }
196	
197	            Population.Update(populationSize, null);
198	            Children.Update(populationSize, null);
199	            fixed (uint* p = cubies) CubiesBuffer.Update(cubies.Length * sizeof(uint), p);
200	            fixed (int* p = solved) SolvedBuffer.Update(solved.Length * sizeof(int), p);
201	            fixed (int* p = active) ActiveBuffer.Update(active.Length * sizeof(int), p);
202	            fixed (int* p = planes) PlanesBuffer.Update(planes.Length * sizeof(int), p);
203	
204	            if (cube.ActiveCubie != null)
205	            {
206	                var moves = cube.FreeMoves.ToArray();
207	                fixed (int* p = moves) FreeMovesBuffer.Update(moves.Length * sizeof(int), p);
208	                // Per-specimen seed sequences for Init: reverse-transform moves that undo active-cluster
209	                // cubies. SEED_RATIO % of the population is seeded (rest random); stride = N-1 genes.
210	                var seedMoves = cube.BuildSeedMoves(TGA<TRubikGenome>.PopulationCount, TAffine.N - 1,
211	                                                    GetDefineValue("SEED_RATIO"), out NumSeeds);
212	                fixed (int* p = seedMoves) SeedMovesBuffer.Update(seedMoves.Length * sizeof(int), p);
213	            }
214	        }
215	
216	        // Scores the current cube on the GPU with the SAME evaluator the GA uses: a zero specimen (all
217	        // genes 0 = 0-degree identity moves after the quarter-turn encoding) leaves the cube unchanged,
218	        // so the evaluator returns baseline + no-op penalty. We subtract the penalty - MEASURED, not
219	        // hardcoded, as the same zero specimen's fitness on a SOLVED cube (baseline == 0, so the fitness
220	        // is exactly the penalty). One scorer (the evaluator), no separate kernel, no magic constant,
221	        // and the baseline tracks any future change to the no-op penalty automatically.
222	        static float noOpPenalty;   // reset to NaN in BuildShaders (Init + on N/SIZE change) -> measured on first ScoreCube
223	        public static float ScoreCube(TRubikCube cube)
224	        {
225	            var score = EvalZeroSpecimen(cube);
226	            if (float.IsNaN(noOpPenalty))
227	                noOpPenalty = EvalZeroSpecimen(new TRubikCube());
228	            return score - noOpPenalty;
229	        }
230	
231	        // Evaluates ONE all-zero specimen (identity
232	        // moves) and returns its fitness = the cube's raw score PLUS the no-op penalty (a zero specimen
233	        // never changes the active cluster, so the penalty always fires).
234	        static float EvalZeroSpecimen(TRubikCube cube)
235	        {
236	            CreateBuffers(cube);
237	            var micro = cube.Cubies.Length <= 64;
238	            var eval = micro ? EvaluateMicroProgram : EvaluateMacroProgram;
239	            var spec = new int[TChromosome.GenesLength + 2];   // all zero = identity moves
240	            fixed (int* p = spec) Population.Update(spec.Length * sizeof(int), p);
241	            OpenGL.UseProgram(eval);
242	            OpenGL.Uniform1ui(4, (uint)cube.SolvedCubies.Count);
243	            OpenGL.Uniform1ui(5, (uint)cube.ActiveCluster.Count);
244	            OpenGL.BindBufferBase(Population.Type, 0, Population.Id);
245	            OpenGL.DispatchCompute(1, 1, 1);                        // one specimen: 1 thread (micro) / 1 block (macro)
246	            OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
247	            var result = new int[1];
248	            OpenGL.BindBuffer(Population.Type, Population.Id);
249	            fixed (int* rp = result)
250	                OpenGL.GetBufferSubData(Population.Type, 0, sizeof(float), rp);
251	            return BitConverter.Int32BitsToSingle(result[0]);
252	        }
253	
254	        // Runs the genetic algorithm on the GPU for the current cube (TRubikGenome.RubikCube /
255	        // TRubikGenome.FreeMoves) and returns the best specimen found.
256	        public static TRubikGenome ExecuteGA()
257	        {
258	            var cube = TRubikGenome.RubikCube;
259	            var populationCount = (uint)TGA<TRubikGenome>.PopulationCount;
260	            var micro = cube.Cubies.Length <= 64;
261	            var evalProgram = micro ? EvaluateMicroProgram : EvaluateMacroProgram;
262	
263	            // Create + upload all buffers for this run (population, packed cube, free moves, indices, planes).
264	            CreateBuffers(cube);
265	            var solvedCount = (uint)cube.SolvedCubies.Count;
266	            var activeCount = (uint)cube.ActiveCluster.Count;
267	
268	            // Dispatch dims. Init/SelCrossover: 1 thread per specimen (blocks of 64).
269	            // Evaluate: micro = 1 thread/specimen; macro = 1 block (256 threads) per specimen.
270	            uint genGroups = (populationCount + 63) / 64;
271	            uint evalGroups = micro ? genGroups : populationCount;
272	
273	            int parentSlot = 0;
274	            var best = new TRubikGenome();
275	            var specimenSize = (TChromosome.GenesLength + 2) * sizeof(int);
276	            var bestBuffer = new int[specimenSize / sizeof(int)];
277	            fixed (int* bestBufPtr = bestBuffer)
278	            {
279	                // Init: fill the population (binding 0) with random valid move sequences.
280	                uint timeSeed = (uint)Random.Shared.Next() | (Random.Shared.Next(2) == 0 ? 0x80000000u : 0u);
281	                OpenGL.UseProgram(InitProgram);
282	                Population.Bind();
283	                OpenGL.Uniform1ui(0, timeSeed);                 // TimeSeed
284	                OpenGL.Uniform1ui(6, NumSeeds);                 // numSeeds
285	                OpenGL.DispatchCompute(genGroups, 1, 1);
286	                OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
287	
288	                var pop = new[] { Population, Children };   // local ping-pong pair (binding 0/1 swap each gen)
289	                for (GenerationsCount = 0; GenerationsCount < TGA<TRubikGenome>.GenerationsCount; GenerationsCount++)
290	                {
291	                    var parent = pop[parentSlot];
292	                    var child = pop[parentSlot ^ 1];
293	
294	                    // 1. Evaluate parents (binding 0). Cluster sizes come from the host, not .length().
295	                    OpenGL.UseProgram(evalProgram);
296	                    OpenGL.Uniform1ui(4, solvedCount);
297	                    OpenGL.Uniform1ui(5, activeCount);
298	                    OpenGL.BindBufferBase(parent.Type, 0, parent.Id);
299	                    OpenGL.DispatchCompute(evalGroups, 1, 1);
300	                    OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
301	
302	                    // 2. Bitonic sort: smallest fitness ends up at index 0. u_Stage=2, u_PassModStage=3.
303	                    OpenGL.UseProgram(SortProgram);
304	                    for (uint stage = 2; stage <= populationCount; stage <<= 1)
305	                    {
306	                        OpenGL.Uniform1ui(2, stage);
307	                        for (uint passModStage = stage >> 1; passModStage > 0; passModStage >>= 1)
308	                        {
309	                            OpenGL.Uniform1ui(3, passModStage);
310	                            OpenGL.DispatchCompute(populationCount / 256, 1, 1);
311	                            OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
312	                        }
313	                    }
314	
315	                    // 3. Read the best specimen (Population[parentSlot][0] after the sort).
316	                    OpenGL.BindBuffer(parent.Type, parent.Id);
317	                    OpenGL.GetBufferSubData(parent.Type, 0, specimenSize, bestBufPtr);
318	                    var fitness = BitConverter.UInt32BitsToSingle((uint)bestBuffer[0]);
319	                    if (fitness < best.Fitness)
320	                    {
321	                        best.ReadBuffer(bestBuffer);
322	                        if (best.Fitness < cube.Score)
323	                            return best;
324	                    }
325	
326	                    // 4. Selection + crossover: parents at binding 0, children written to binding 1.
327	                    OpenGL.UseProgram(SelCrossoverProgram);
328	                    OpenGL.BindBufferBase(parent.Type, 0, parent.Id);
329	                    OpenGL.BindBufferBase(child.Type, 1, child.Id);
330	                    OpenGL.Uniform1ui(0, timeSeed++);           // TimeSeed
331	                    OpenGL.Uniform1ui(6, NumSeeds);             // numSeeds
332	                    OpenGL.DispatchCompute(genGroups, 1, 1);
333	                    OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
334	
335	                    // 5. Ping-pong: this generation's children are next generation's parents.
336	                    parentSlot ^= 1;
337	                }
338	            }
339	            return best;
340	        }
341	
342	        // Compiles one render shader (VS/FS) with N injected into its own #define (not the Setup header).
343	        static void CompileRenderProgram()
344	        {
345	            var dotPath = "Resources.CubeVertex.glsl.c";
346	            var code = ReadManifestText(dotPath).Replace("#include \"Variables.glsl.c\"", Variables);
347	            OpenGL.CompileShader(renderVs, code);
348	            dotPath = "Resources.CubeFragment.glsl.c";
349	            code = ReadManifestText(dotPath);
350	            OpenGL.CompileShader(renderFs, code);
351	            OpenGL.LinkProgram(RenderProgram);
352	        }
353	
354	        // (Re)builds the shared base hypercube mesh into the render buffers from TCubie.Cube: base ND
355	        // positions -> PosBuffer (vertex-pulled), interleaved uv+color -> VAO, triangulated quads -> EBO.
356	        static void BuildCubeMesh()
357	        {
358	            TCubie.Cube = TShape.CreateHyperCube();
359	            var mesh = TCubie.Cube;
360	            int n = TAffine.N;
361	            int faceCount = mesh.Colors.Count;      // one color per quad face
362	            int vertCount = 4 * faceCount;          // quads expanded per-face (uv/color differ per face)
363	            cubeIndexCount = 6 * faceCount;         // two triangles per quad
364	
365	            var pos = new float[n * vertCount];
366	            var attr = new byte[12 * vertCount];    // interleaved: uv (2 float) + color (4 byte)
367	            var idx = new uint[cubeIndexCount];
368	            var quadUv = new float[] { 0, 0, 1, 0, 1, 1, 0, 1 };
369	            fixed (byte* pa = attr)
370	            {
371	                for (int f = 0; f < faceCount; f++)
372	                {
373	                    var col = mesh.Colors[f];
374	                    for (int k = 0; k < 4; k++)
375	                    {
376	                        int v = 4 * f + k;
377	                        var corner = mesh.Vertices[mesh.Faces[4 * f + k]];
378	                        for (int d = 0; d < n; d++)
379	                            pos[n * v + d] = corner.Data[d];
380	                        float* fu = (float*)(pa + 12 * v);
381	                        fu[0] = quadUv[2 * k];
382	                        fu[1] = quadUv[2 * k + 1];
383	                        byte* bc = pa + 12 * v + 8;
384	                        bc[0] = col.R; bc[1] = col.G; bc[2] = col.B; bc[3] = 255;
385	                    }
386	                    int b = 4 * f, o = 6 * f;
387	                    idx[o] = (uint)b; idx[o + 1] = (uint)(b + 1); idx[o + 2] = (uint)(b + 2);
388	                    idx[o + 3] = (uint)b; idx[o + 4] = (uint)(b + 2); idx[o + 5] = (uint)(b + 3);
389	                }
390	            }
391	
392	            OpenGL.BindVertexArray(cubeVao);
393	            OpenGL.BindBuffer(OpenGL.GL_ARRAY_BUFFER, attrBuf);
394	            fixed (byte* pa = attr)
395	                OpenGL.BufferData(OpenGL.GL_ARRAY_BUFFER, attr.Length, pa, OpenGL.GL_STATIC_DRAW);
396	            OpenGL.VertexAttribPointer(0, 2, OpenGL.GL_FLOAT, (byte)0, 12, (void*)0);           // uv
397	            OpenGL.EnableVertexAttribArray(0);
398	            OpenGL.VertexAttribPointer(1, 4, OpenGL.GL_UNSIGNED_BYTE, (byte)1, 12, (void*)8);   // color (normalized)
399	            OpenGL.EnableVertexAttribArray(1);
400	            OpenGL.BindBuffer(OpenGL.GL_ELEMENT_ARRAY_BUFFER, idxBuf);
401	            fixed (uint* pi = idx)
402	                OpenGL.BufferData(OpenGL.GL_ELEMENT_ARRAY_BUFFER, idx.Length * sizeof(uint), pi, OpenGL.GL_STATIC_DRAW);
403	            OpenGL.BindVertexArray(0);
404	
405	            fixed (float* pp = pos) PosBuffer.Update(pos.Length * sizeof(float), pp);
406	        }
407	
408	        // Draws every cubie as an instance of the shared base mesh. TGLContext gathers the accumulated ND
409	        // world transforms (Root * ... * cubie) and passes them; we pack M (column-major) + Origin per
410	        // instance into XformBuffer and issue one instanced draw. Rebuilds programs+mesh on N/SIZE change.
411	        public static void DrawCube(List<TAffine> instances)
412	        {
413	            if (CompiledN != TAffine.N || CompiledSize != TRubikCube.Size)
414	                BuildShaders();
415	
416	            int n = TAffine.N, inst = instances.Count, stride = n * n + n;
417	            if (xformScratch == null || xformScratch.Length < stride * inst)
418	                xformScratch = new float[stride * inst];
419	            for (int i = 0; i < inst; i++)
420	            {
421	                Array.Copy(instances[i].M.Data, 0, xformScratch, i * stride, n * n);           // M (column-major)
422	                Array.Copy(instances[i].Origin.Data, 0, xformScratch, i * stride + n * n, n);   // Origin
423	            }
424	            fixed (float* p = xformScratch) XformBuffer.Update(stride * inst * sizeof(float), p);
425	
426	            OpenGL.UseProgram(RenderProgram);
427	            PosBuffer.Bind();       // binding 8
428	            XformBuffer.Bind();     // binding 9
429	            OpenGL.BindVertexArray(cubeVao);
430	            OpenGL.DrawElementsInstanced(OpenGL.GL_TRIANGLES, cubeIndexCount, OpenGL.GL_UNSIGNED_INT, (void*)0, inst);
431	            OpenGL.BindVertexArray(0);
432	        }
433	    }
434	}
