        public List<TVector> EulerAngles;

        TShape _Parent;
        public virtual TShape Parent
        {
            get { return _Parent; }
            set
            {
                if (value == _Parent) return;
                _Parent?.Children.Remove(this);
                _Parent = value;
                _Parent?.Children.Add(this);
            }
        }
        public TAffine Transform = new TAffine();
