            //        cube.Faces.Add(firstIdx | axis2);
            //        cube.Colors.Add(pal[255 * colorIdx / colorCount]);
            //        colorIdx++;
            //    }
            //}
            for (int axis = 0; axis < TAffine.N; axis++)
            {
                for (int slice = 0; slice < TRubikCube.Size; slice++)
                {

                }
            }
            return cube;
        }


    }
}

