#version 430
// Step 1: flat per-face color, straight through. The orientation texture, diffuse lighting
// (normal + TBN derived from screen-space derivatives) and normal mapping arrive later as an
// additive layer here; transparency (weighted-blended OIT) is a separate pass.
in vec2 fUv;
in vec4 fCol;
in vec3 fPos;
out vec4 outColor;
void main()
