// Draws every cubie as an instance of the shared base mesh. TGLContext gathers the accumulated ND
// world transforms (Root * ... * cubie) and passes them; we pack M (column-major) + Origin per
// instance into XformBuffer and issue one instanced draw. Rebuilds programs+mesh on N/SIZE change.
public static void DrawCube(List<TAffine> instances)
{
    if (CompiledN != TAffine.N || CompiledSize != TRubikCube.Size)
        BuildShaders();

    int n = TAffine.N, inst = instances.Count, stride = n * n + n;
    if (xformScratch == null || xformScratch.Length < stride * inst)
        xformScratch = new float[stride * inst];
    for (int i = 0; i < inst; i++)
    {
        Array.Copy(instances[i].M.Data, 0, xformScratch, i * stride, n * n);           // M (column-major)
        Array.Copy(instances[i].Origin.Data, 0, xformScratch, i * stride + n * n, n);   // Origin
    }
    fixed (float* p = xformScratch) XformBuffer.Update(stride * inst * sizeof(float), p);

    OpenGL.UseProgram(RenderProgram);
    PosBuffer.Bind();       // binding 8
    XformBuffer.Bind();     // binding 9
    OpenGL.BindVertexArray(cubeVao);
    OpenGL.DrawElementsInstanced(OpenGL.GL_TRIANGLES, cubeIndexCount, OpenGL.GL_UNSIGNED_INT, (void*)0, inst);
    OpenGL.BindVertexArray(0);
}

