#version 430
// Instanced hypercube render. N is injected at compile time (like the GA shaders).
// Base positions are ND (may exceed a vec4), so they are vertex-pulled from an SSBO by
// gl_VertexID; the per-instance ND world transform (M column-major + Origin) is pulled
// from another SSBO by gl_InstanceID. Projection = orthographic (drop coords >= 3).
#include "Variables.glsl.c"
layout(std430, binding = 8) buffer Pos    { float basePos[]; };   // N floats per base vertex
layout(std430, binding = 9) buffer Xforms { float world[];   };   // (N*N + N) floats per instance

layout(location = 0) in vec2 uv;
layout(location = 1) in vec4 color;

out vec2 fUv;
out vec4 fCol;
out vec3 fPos;
flat out vec3 fNormal;

// Orthographic ND->3D projection of base vertex `vid` for the current instance: keep the first
// up-to-3 coords of the ND world position (M * p + Origin), M stored column-major.
vec3 project(int vid)
{
    int vb = vid * N;
    int mb = gl_InstanceID * (N * N + N);
    vec3 p = vec3(0.0);
    for (int r = 0; r < min(N, 3); r++)
    {
        float s = world[mb + N * N + r];                    // Origin[r]
        for (int c = 0; c < N; c++)
            s += world[mb + c * N + r] * basePos[vb + c];   // M[r,c] * p[c]
        p[r] = s;
    }
    return p;
}

void main()
{
    vec3 p3 = project(gl_VertexID);
    gl_Position = vec4(p3, 1.0);
    fPos = p3;

    // Flat face normal from the quad's own 4 consecutive corners, projected to 3D (replaces the old
    // fragment-shader dFdx/dFdy derivative trick). A face whose 2D plane lies in the dropped ND
    // dimensions projects to a line/point (zero-area) - fall back to facing the viewer.
    int c0 = gl_VertexID & ~3;                              // first corner of this quad (= 4 * face)
    vec3 nrm = cross(project(c0 + 1) - project(c0), project(c0 + 3) - project(c0));
    fNormal = length(nrm) > 1e-6 ? normalize(nrm) : vec3(0.0, 0.0, 1.0);

    fUv = uv;
    fCol = color;
}

