#version 430
#include "Variables.glsl.c"
// First lighting pass: flat per-face base color modulated by the scene lights (ambient + diffuse +
// specular). The ND mesh carries no normals, so the face normal is reconstructed from screen-space
// derivatives of the projected position. Normal mapping and weighted-blended OIT transparency come later.
in vec2 fUv;
in vec4 fCol;
in vec3 fPos;
out vec4 outColor;

// std140 light record. Each vec3 is padded to a vec4 so the C# host packing is trivial; the .w slots
// carry flags/counts. Position.w = isDirectional (then .xyz is the direction toward the light).
struct Light {
    vec4 Position;   // xyz world position (or direction); w = isDirectional
    vec4 Ambient;    // xyz
    vec4 Diffuse;    // xyz
    vec4 Specular;   // xyz
    vec4 Att;        // xyz = constant / linear / quadratic attenuation
};

layout(std140, binding = 10) uniform LightsBuffer {
    vec4 LightHeader;              // x = number of active lights
    Light Lights[MAX_LIGHTS];
};

void main()
{
    int count = int(LightHeader.x);
    if (count == 0)               // no lights uploaded -> keep the flat unlit color
    {
        outColor = fCol;
        return;
    }

    // Face normal from the projected position's screen-space derivatives, oriented toward the viewer
    // (the ND->3D projection is orthographic, so the view direction is constant +Z).
    vec3 N = normalize(cross(dFdx(fPos), dFdy(fPos)));
    if (N.z < 0.0) N = -N;
    vec3 V = vec3(0.0, 0.0, 1.0);

    vec3 lit = vec3(0.0);
    for (int i = 0; i < count; i++)
    {
        Light lgt = Lights[i];
        vec3 L;
        float att = 1.0;
        if (lgt.Position.w != 0.0)                 // directional
            L = normalize(lgt.Position.xyz);
        else
        {
            vec3 d = lgt.Position.xyz - fPos;
            float dist = length(d);
            L = d / max(dist, 1e-4);
            att = 1.0 / (lgt.Att.x + lgt.Att.y * dist + lgt.Att.z * dist * dist);
        }
        float diff = max(dot(N, L), 0.0);
        vec3 H = normalize(L + V);
        float spec = pow(max(dot(N, H), 0.0), 32.0);
        lit += lgt.Ambient.xyz + att * (diff * lgt.Diffuse.xyz + spec * lgt.Specular.xyz);
    }
    outColor = vec4(fCol.rgb * lit, fCol.a);
}

