11	
12	// std140 light record. Each vec3 is padded to a vec4 so the C# host packing is trivial; the .w slots
13	// carry flags/counts. Position.w = isDirectional (then .xyz is the direction toward the light).
14	struct Light {
15	    vec4 Position;   // xyz world position (or direction); w = isDirectional
16	    vec4 Ambient;    // xyz
17	    vec4 Diffuse;    // xyz
