#version 430
#include "Variables.glsl.c"
// Lighting pass: base color (diffuse) modulated by the scene lights (ambient + diffuse + specular).
// The vertex shader supplies a flat per-face TBN frame (tangent/bitangent from the quad's texture-
// coordinate axes, normal from their cross) plus the per-face material specular color + shininess.
// Weighted-blended OIT transparency comes later.
in vec2 fUv;
in vec4 fCol;
in vec3 fPos;
flat in vec3 fNormal;
flat in vec3 fTangent;
flat in vec3 fBitangent;
flat in vec3 fMatSpec;
flat in float fShininess;
out vec4 outColor;

// std140 light record. Each vec3 is padded to a vec4 so the C# host packing is trivial; the .w slots
// carry flags/counts. Position.w = isDirectional (then .xyz is the direction toward the light).
struct Light {
    vec4 Position;   // xyz world position (or direction); w = isDirectional
    vec4 Ambient;    // xyz
    vec4 Diffuse;    // xyz
    vec4 Specular;   // xyz
    vec4 Att;        // xyz = constant / linear / quadratic attenuation
};

layout(std140, binding = 10) uniform LightsBuffer {
    vec4 LightHeader;              // x = number of active lights
    Light Lights[MAX_LIGHTS];
};

void main()
{
    int count = int(LightHeader.x);
    if (count == 0)               // no lights uploaded -> keep the flat unlit color
    {
        outColor = fCol;
        return;
    }

    // Orient the face toward the viewer (the ND->3D projection is orthographic, so the view direction
    // is a constant +Z). Not named N - that is the dimension macro (#define N ...) from Variables.
    vec3 nrm = fNormal;
    if (nrm.z < 0.0) nrm = -nrm;

    // TBN frame. No normal map yet, so the tangent-space normal is flat (0,0,1) and the world normal is
    // just nrm; when material normal maps arrive, replace the constant with texture(NormalMap, fUv)*2-1.
    mat3 TBN = mat3(normalize(fTangent), normalize(fBitangent), nrm);
    vec3 tangentNormal = vec3(0.0, 0.0, 1.0);
    vec3 Nw = normalize(TBN * tangentNormal);

    vec3 V = vec3(0.0, 0.0, 1.0);
    vec3 matDiffuse = fCol.rgb;                        // per-face diffuse color (from the material)
    vec3 matSpecular = fMatSpec;                       // per-face specular color (from the material)

    vec3 lit = vec3(0.0);
    for (int i = 0; i < count; i++)
    {
        Light lgt = Lights[i];
        vec3 L;
        float att = 1.0;
        if (lgt.Position.w != 0.0)                 // directional
            L = normalize(lgt.Position.xyz);
        else
        {
            vec3 d = lgt.Position.xyz - fPos;
            float dist = length(d);
            L = d / max(dist, 1e-4);
            att = 1.0 / (lgt.Att.x + lgt.Att.y * dist + lgt.Att.z * dist * dist);
        }
        vec3 ambient = lgt.Ambient.xyz * matDiffuse;
        float diff = max(dot(Nw, L), 0.0);
        vec3 diffuse = lgt.Diffuse.xyz * matDiffuse * diff;
        vec3 H = normalize(L + V);
        float spec = pow(max(dot(Nw, H), 0.0), max(fShininess, 1.0));
        vec3 specular = lgt.Specular.xyz * matSpecular * spec;
        lit += ambient + att * (diffuse + specular);
    }
    outColor = vec4(lit, fCol.a);
}

