// coords of the ND world position (M * p + Origin), M stored column-major.
vec3 project(int vid, int inst)
{
    int vb = vid * N;
    int mb = inst * STRIDE;
    vec3 p = vec3(0.0);
    for (int r = 0; r < min(N, 3); r++)
    {
        float s = world[mb + N * N + r];                    // Origin[r]
        for (int c = 0; c < N; c++)
            s += world[mb + c * N + r] * basePos[vb + c];   // M[r,c] * p[c]
        p[r] = s;
    }
    return p;
}

