        // base mesh). TGLContext owns the scene graph; Gpu owns the render pipeline (Gpu.DrawCube).
        void GatherInstances(TShape obj, TAffine parent, List<TAffine> list)
        {
            var world = parent * obj.Transform;
            if (obj.Faces.Count > 0) list.Add(world);
            foreach (var child in obj.Children)
                GatherInstances(child, world, list);
        }

