        static List<TAffine> AllOrientations()
        {
            var seen = new Dictionary<uint, TAffine>();
            var queue = new Queue<TAffine>();
            var id = new TAffine();
            seen[id.OrthoPack()] = id;
            queue.Enqueue(id);
            while (queue.Count > 0)
            {
                var o = queue.Dequeue();
                for (int plane = 0; plane < TAffine.Planes.Length; plane++)
                    for (int angle = 1; angle <= 3; angle++)
                    {
                        var c = ApplyMove(o, plane, angle);
                        var k = c.OrthoPack();
                        if (!seen.ContainsKey(k)) { seen[k] = c; queue.Enqueue(c); }
                    }
            }
            return new List<TAffine>(seen.Values);
        }

        // Every shortest (plane, angle) sequence the greedy can produce under permutation perms[permIdx]:
        // branch on ALL quarter-turns that drop the permuted RotationCount by one (a full tree, not random).
        static HashSet<string> AllGreedy(TAffine o, int permIdx)
        {
            var results = new HashSet<string>();
            Dfs(o, permIdx, RotCount(o, permIdx), new List<int>(), results);
            return results;
        }

        static void Dfs(TAffine o, int permIdx, int rc, List<int> seq, HashSet<string> results)
        {
            if (rc == 0) { results.Add(string.Join(" ", seq)); return; }
            for (int plane = 0; plane < TAffine.Planes.Length; plane++)
                for (int angle = 1; angle <= 3; angle++)
                {
                    var c = ApplyMove(o, plane, angle);
                    if (RotCount(c, permIdx) == rc - 1)
                    {
                        seq.Add(plane * 4 + angle);
                        Dfs(c, permIdx, rc - 1, seq, results);
                        seq.RemoveAt(seq.Count - 1);
                    }
                }
        }

        // Moves-to-solve of orientation o measured after permuting its axes by perms[permIdx]: count the
        // non-identity Givens rotations of the STANDARD-order QR of PᵀMP.
        static int RotCount(TAffine o, int permIdx)
        {
            long key = ((long)o.OrthoPack() << 10) | (uint)permIdx;
            if (rotMemo.TryGetValue(key, out var cached)) return cached;

            int n = TAffine.N;
            var perm = perms[permIdx];
            var t = new TAffine();
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++)
                    t.M[y, x] = o.M[perm[y], perm[x]];
            var angles = t.GetEulerAngles(null);
            int c = 0;
            foreach (var a in angles)
                if (TCubie.GetAngle(a[0], a[1]) != 0) c++;

            rotMemo[key] = c;
            return c;
        }

        static TAffine ApplyMove(TAffine o, int plane, int angle)
        {
            var c = o.Clone();
            var pa = TAffine.Planes[plane];
            var rot = TCubie.SetAngle(angle);
            c.Rotate(pa[0], pa[1], rot.X, rot.Y);
            return c;
        }

        static int Len(string seq)   // number of moves in a space-joined sequence ("" = solved, length 0)
        {
            if (seq.Length == 0) return 0;
            int c = 1;
            foreach (var ch in seq) if (ch == ' ') c++;
            return c;
        }

        static string ExampleExtra(TAffine o, HashSet<string> idSet, HashSet<string> union)
        {
            foreach (var s in union)
                if (!idSet.Contains(s))
                    return s.Length == 0 ? "(empty)" : s;
            return null;
        }

        static int[][] Permutations(int n)
        {
            var nums = new int[n];
            for (int i = 0; i < n; i++) nums[i] = i;
            var res = new List<int[]>();
            Permute(nums, 0, res);
            return res.ToArray();
        }

        static void Permute(int[] a, int k, List<int[]> res)
        {
            if (k == a.Length) { res.Add((int[])a.Clone()); return; }
            for (int i = k; i < a.Length; i++)
            {
                (a[k], a[i]) = (a[i], a[k]);
                Permute(a, k + 1, res);
                (a[k], a[i]) = (a[i], a[k]);
            }
        }
    }
}

