using System;
using System.Collections.Generic;
using System.Text;
using TGL;

namespace RubikCube
{
    // Diagnostic (not in the production path). Question: the greedy solves a cubie by repeatedly taking a
    // quarter-turn that lowers RotationCount, and RotationCount = number of non-identity Givens rotations in
    // the STANDARD-order QR of the orientation matrix. Permuting the axes before that QR (A[y,x] = M[perm[y],
    // perm[x]] = PᵀMP, then standard decomposition) changes which moves count as progress, so the greedy can
    // reach different shortest sequences. This measures how many distinct solving sequences the greedy can
    // produce under the identity permutation vs. the union over all N! axis permutations, over EVERY cubie
    // orientation (the rotation group: 24 for N=3, 192 for N=4). Nothing here touches TCubie.State - RotCount
    // is computed locally, so the comparison is self-contained and independent of the production metric.
    //
    // Sequences are compared as MANOEUVRES, not raw (plane, angle) tokens: each is realised into genes with
    // the first valid axis (the axis is irrelevant to the target solve; a fixed choice keeps sequences
    // comparable) and slice 0, then reduced by the composition of TRubikGenome.Correct (consecutive same
    // axis+plane+slice quarter-turns fold mod 4; slice along a collateral axis is invariant under same-plane
    // moves, so 0 is faithful). This collapses effect-equivalent forms - 2x90 folds to one 180 - so only
    // genuinely different net manoeuvres are counted, not move-count-padded duplicates.
    static class TGreedyDiversity
    {
        static int[][] perms;                    // all N! axis permutations (index 0 = identity)
        static Dictionary<long, int> rotMemo;    // RotCount keyed by (OrthoPack << 10 | permIdx)

        public static string Run()
        {
            int n = TAffine.N;
            perms = Permutations(n);
            rotMemo = new Dictionary<long, int>();
            var orientations = AllOrientations();

            long sumId = 0, sumUnion = 0;
            int gained = 0, maxDelta = 0;
            string example = null;
            // Distinct sequences bucketed by length: identity metric vs. only-reachable-via-permutation.
            // A shortest path has length = starting RotCount <= plane count, so that + 1 sizes the buckets.
            var histId = new int[TAffine.Planes.Length + 1];
            var histExtra = new int[TAffine.Planes.Length + 1];

            foreach (var o in orientations)
            {
                var idSet = AllGreedy(o, 0);                     // permIdx 0 = identity
                var union = new HashSet<string>(idSet);
                for (int p = 1; p < perms.Length; p++)
                    union.UnionWith(AllGreedy(o, p));

                sumId += idSet.Count;
                sumUnion += union.Count;
                int delta = union.Count - idSet.Count;
                if (delta > 0)
                {
                    gained++;
                    if (delta > maxDelta) { maxDelta = delta; example = ExampleExtra(o, idSet, union); }
                }
                foreach (var s in idSet) histId[Len(s)]++;
                foreach (var s in union) if (!idSet.Contains(s)) histExtra[Len(s)]++;
            }

            int count = orientations.Count;
            var sb = new StringBuilder();
            sb.AppendLine($"Greedy decomposition diversity  (N = {n})");
            sb.AppendLine($"  cubie orientations (rotation group) : {count}");
            sb.AppendLine($"  axis permutations (N!)             : {perms.Length}");
            sb.AppendLine();
            sb.AppendLine($"  distinct sequences, identity metric : {sumId}   (avg {sumId / (double)count:0.00} / orientation)");
            sb.AppendLine($"  distinct sequences, union over perms: {sumUnion}   (avg {sumUnion / (double)count:0.00} / orientation)");
            sb.AppendLine($"  extra from permuting axes           : {sumUnion - sumId}   (+{(sumId == 0 ? 0 : 100.0 * (sumUnion - sumId) / sumId):0.0}%)");
            sb.AppendLine();
            sb.AppendLine($"  orientations where perms add paths  : {gained} / {count}");
            sb.AppendLine($"  max extra paths on one orientation  : {maxDelta}");
            if (example != null)
                sb.AppendLine($"  example path only reachable via perm: {example}");
            sb.AppendLine();
            sb.AppendLine("  distinct sequences by length:");
            sb.AppendLine("    length   identity   extra(perm)");
            for (int L = 0; L < histId.Length; L++)
                if (histId[L] > 0 || histExtra[L] > 0)
                    sb.AppendLine($"    {L,6}   {histId[L],8}   {histExtra[L],10}");
            return sb.ToString();
        }

        // All reachable cubie orientations, generated by closing the identity under every quarter-turn.
        // Convention-safe: the same Rotate that Turn uses, keyed by the packed signed-permutation (OrthoPack).
        static List<TAffine> AllOrientations()
        {
            var seen = new Dictionary<uint, TAffine>();
            var queue = new Queue<TAffine>();
            var id = new TAffine();
            seen[id.OrthoPack()] = id;
            queue.Enqueue(id);
            while (queue.Count > 0)
            {
                var o = queue.Dequeue();
                for (int plane = 0; plane < TAffine.Planes.Length; plane++)
                    for (int angle = 1; angle <= 3; angle++)
                    {
                        var c = ApplyMove(o, plane, angle);
                        var k = c.OrthoPack();
                        if (!seen.ContainsKey(k)) { seen[k] = c; queue.Enqueue(c); }
                    }
            }
            return new List<TAffine>(seen.Values);
        }

        // Every shortest (plane, angle) sequence the greedy can produce under permutation perms[permIdx]:
        // branch on ALL quarter-turns that drop the permuted RotationCount by one (a full tree, not random).
        static HashSet<string> AllGreedy(TAffine o, int permIdx)
        {
            var results = new HashSet<string>();
            Dfs(o, permIdx, RotCount(o, permIdx), new List<int>(), results);
            return results;
        }

        static void Dfs(TAffine o, int permIdx, int rc, List<int> seq, HashSet<string> results)
        {
            if (rc == 0) { results.Add(CorrectKey(seq)); return; }
            for (int plane = 0; plane < TAffine.Planes.Length; plane++)
                for (int angle = 1; angle <= 3; angle++)
                {
                    var c = ApplyMove(o, plane, angle);
                    if (RotCount(c, permIdx) == rc - 1)
                    {
                        seq.Add(plane * 4 + angle);
                        Dfs(c, permIdx, rc - 1, seq, results);
                        seq.RemoveAt(seq.Count - 1);
                    }
                }
        }

        // Moves-to-solve of orientation o measured after permuting its axes by perms[permIdx]: count the
        // non-identity Givens rotations of the STANDARD-order QR of PᵀMP.
        static int RotCount(TAffine o, int permIdx)
        {
            long key = ((long)o.OrthoPack() << 10) | (uint)permIdx;
            if (rotMemo.TryGetValue(key, out var cached)) return cached;

            int n = TAffine.N;
            var perm = perms[permIdx];
            var t = new TAffine();
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++)
                    t.M[y, x] = o.M[perm[y], perm[x]];
            var angles = t.GetEulerAngles(null);
            int c = 0;
            foreach (var a in angles)
                if (TCubie.GetAngle(a[0], a[1]) != 0) c++;

            rotMemo[key] = c;
            return c;
        }

        static TAffine ApplyMove(TAffine o, int plane, int angle)
        {
            var c = o.Clone();
            var pa = TAffine.Planes[plane];
            var rot = TCubie.SetAngle(angle);
            c.Rotate(pa[0], pa[1], rot.X, rot.Y);
            return c;
        }

        static int Len(string seq)   // number of moves in a space-joined sequence ("" = solved, length 0)
        {
            if (seq.Length == 0) return 0;
            int c = 1;
            foreach (var ch in seq) if (ch == ' ') c++;
            return c;
        }

        static string ExampleExtra(TAffine o, HashSet<string> idSet, HashSet<string> union)
        {
            foreach (var s in union)
                if (!idSet.Contains(s))
                    return s.Length == 0 ? "(empty)" : s;
            return null;
        }

        static int[][] Permutations(int n)
        {
            var nums = new int[n];
            for (int i = 0; i < n; i++) nums[i] = i;
            var res = new List<int[]>();
            Permute(nums, 0, res);
            return res.ToArray();
        }

        static void Permute(int[] a, int k, List<int[]> res)
        {
            if (k == a.Length) { res.Add((int[])a.Clone()); return; }
            for (int i = k; i < a.Length; i++)
            {
                (a[k], a[i]) = (a[i], a[k]);
                Permute(a, k + 1, res);
                (a[k], a[i]) = (a[i], a[k]);
            }
        }
    }
}

