// Moves-to-solve of orientation o measured after permuting its axes by perms[permIdx]: count the
// non-identity Givens rotations of the QR of PᵀMP. reversed = decompose the transpose (the M^T route).
static int RotCount(TAffine o, int permIdx, bool reversed)
{
    long key = ((long)o.OrthoPack() << 11) | ((uint)permIdx << 1) | (reversed ? 1u : 0u);
    if (rotMemo.TryGetValue(key, out var cached)) return cached;

    int n = TAffine.N;
    var perm = perms[permIdx];
    var t = new TAffine();
    for (int y = 0; y < n; y++)
        for (int x = 0; x < n; x++)
            t.M[y, x] = o.M[perm[y], perm[x]];
    var angles = t.GetEulerAngles(null, reversed);
    int c = 0;
    foreach (var a in angles)
        if (TCubie.GetAngle(a[0], a[1]) != 0) c++;

    rotMemo[key] = c;
    return c;
}

