static double Pct(long baseVal, long total) => baseVal == 0 ? 0 : 100.0 * (total - baseVal) / baseVal;

public static string Run()
{
    int n = TAffine.N;
    perms = Permutations(n);
    rotMemo = new Dictionary<long, int>();
    var orientations = AllOrientations();

    long sumId = 0, sumRev = 0, sumPerm = 0, sumFull = 0;
    int gainedRev = 0, maxDeltaRev = 0;
    string example = null;
    // Distinct manoeuvres bucketed by length: baseline (standard QR) vs. only-reachable-via the
    // reversed (M^T) route. A shortest path has length <= plane count, so that + 1 sizes the buckets.
    var histId = new int[TAffine.Planes.Length + 1];
    var histExtra = new int[TAffine.Planes.Length + 1];

    foreach (var o in orientations)
    {
        var idSet = AllGreedy(o, 0, false);                   // standard QR, identity perm = baseline

        var revUnion = new HashSet<string>(idSet);           // measured: + transposition (M^T route)
        revUnion.UnionWith(AllGreedy(o, 0, true));

        var permUnion = new HashSet<string>(idSet);          // reference: + axis permutations
        for (int p = 1; p < perms.Length; p++)
            permUnion.UnionWith(AllGreedy(o, p, false));

        var fullUnion = new HashSet<string>(permUnion);      // reference: both axes (perm x reversed)
        fullUnion.UnionWith(revUnion);
        for (int p = 1; p < perms.Length; p++)
            fullUnion.UnionWith(AllGreedy(o, p, true));

        sumId += idSet.Count;
        sumRev += revUnion.Count;
        sumPerm += permUnion.Count;
        sumFull += fullUnion.Count;

        int delta = revUnion.Count - idSet.Count;
        if (delta > 0)
        {
            gainedRev++;
            if (delta > maxDeltaRev) { maxDeltaRev = delta; example = ExampleExtra(o, idSet, revUnion); }
        }
        foreach (var s in idSet) histId[Len(s)]++;
        foreach (var s in revUnion) if (!idSet.Contains(s)) histExtra[Len(s)]++;
    }

    int count = orientations.Count;
    var sb = new StringBuilder();
    sb.AppendLine($"Greedy decomposition diversity  (N = {n})");
    sb.AppendLine($"  cubie orientations (rotation group) : {count}");
    sb.AppendLine($"  axis permutations (N!)              : {perms.Length}");
    sb.AppendLine();
    sb.AppendLine($"  baseline (standard QR)              : {sumId}   (avg {sumId / (double)count:0.00} / orientation)");
    sb.AppendLine($"  + transposition (reversed, M^T)     : {sumRev}   (+{Pct(sumId, sumRev):0.0}%)   <- measured");
    sb.AppendLine();
    sb.AppendLine("  reference:");
    sb.AppendLine($"  + axis permutations (N!)            : {sumPerm}   (+{Pct(sumId, sumPerm):0.0}%)");
    sb.AppendLine($"  + both (perms x reversed)           : {sumFull}   (+{Pct(sumId, sumFull):0.0}%)");
    sb.AppendLine();
    sb.AppendLine($"  orientations where reversed adds    : {gainedRev} / {count}");
    sb.AppendLine($"  max extra on one orientation        : {maxDeltaRev}");
    if (example != null)
        sb.AppendLine($"  example only reachable via reversed : {example}");
    sb.AppendLine();
    sb.AppendLine("  distinct manoeuvres by length (moves after Correct):");
    sb.AppendLine("    length   identity   extra(rev)");
    for (int L = 0; L < histId.Length; L++)
        if (histId[L] > 0 || histExtra[L] > 0)
            sb.AppendLine($"    {L,6}   {histId[L],8}   {histExtra[L],10}");
    return sb.ToString();
}

// All reachable cubie orientations, generated by closing the identity under every quarter-turn.
// Convention-safe: the same Rotate that Turn uses, keyed by the packed signed-permutation (OrthoPack).
static List<TAffine> AllOrientations()
{
    var seen = new Dictionary<uint, TAffine>();
    var queue = new Queue<TAffine>();
    var id = new TAffine();
    seen[id.OrthoPack()] = id;
    queue.Enqueue(id);
    while (queue.Count > 0)
    {
        var o = queue.Dequeue();
        for (int plane = 0; plane < TAffine.Planes.Length; plane++)
            for (int angle = 1; angle <= 3; angle++)
            {
                var c = ApplyMove(o, plane, angle);
                var k = c.OrthoPack();
                if (!seen.ContainsKey(k)) { seen[k] = c; queue.Enqueue(c); }
            }
    }
    return new List<TAffine>(seen.Values);
}

// Every shortest manoeuvre the greedy can produce under the metric (permutation perms[permIdx],
// reversed = M^T route): branch on ALL quarter-turns that drop that RotationCount by one.
static HashSet<string> AllGreedy(TAffine o, int permIdx, bool reversed)
{
    var results = new HashSet<string>();
    Dfs(o, permIdx, reversed, RotCount(o, permIdx, reversed), new List<int>(), results);
    return results;
}

static void Dfs(TAffine o, int permIdx, bool reversed, int rc, List<int> seq, HashSet<string> results)
{
    if (rc == 0) { results.Add(CorrectKey(seq)); return; }
    for (int plane = 0; plane < TAffine.Planes.Length; plane++)
        for (int angle = 1; angle <= 3; angle++)
        {
            var c = ApplyMove(o, plane, angle);
            if (RotCount(c, permIdx, reversed) == rc - 1)
            {
                seq.Add(plane * 4 + angle);
                Dfs(c, permIdx, reversed, rc - 1, seq, results);
                seq.RemoveAt(seq.Count - 1);
            }
        }
}

