// All valid QR plane orders, enumerated by the same zero-propagation rule GetOrder samples from:
// a plane (a,b) is eligible once a == 0, or both mask[b,a-1] and mask[a,a-1] are set. orders[0] is
// the standard order (lowest eligible plane first == [0,1,2,...]).
static List<int>[] AllOrders()
{
    var results = new List<List<int>>();
    OrderDfs(new List<int>(), new bool[TAffine.N, TAffine.N], results);
    return results.ToArray();
}

static void OrderDfs(List<int> order, bool[,] mask, List<List<int>> results)
{
    int planeCount = TAffine.Planes.Length;
    if (order.Count == planeCount) { results.Add(new List<int>(order)); return; }
    for (int p = 0; p < planeCount; p++)
    {
        if (order.Contains(p)) continue;
        int a = TAffine.Planes[p][0], b = TAffine.Planes[p][1];
        if (!(a == 0 || (mask[b, a - 1] && mask[a, a - 1]))) continue;
        mask[b, a] = true; order.Add(p);
        OrderDfs(order, mask, results);
        order.RemoveAt(order.Count - 1); mask[b, a] = false;
    }
}

// Every shortest manoeuvre the greedy can produce under the metric (axis permutation perms[permIdx],
// QR plane order orders[orderIdx], reversed = M^T route): branch on ALL quarter-turns that drop that
// RotationCount by one.
static HashSet<string> AllGreedy(TAffine o, int permIdx, int orderIdx, bool reversed)
{
    var results = new HashSet<string>();
    Dfs(o, permIdx, orderIdx, reversed, RotCount(o, permIdx, orderIdx, reversed), new List<int>(), results);
    return results;
}

static void Dfs(TAffine o, int permIdx, int orderIdx, bool reversed, int rc, List<int> seq, HashSet<string> results)
{
    if (rc == 0) { results.Add(CorrectKey(seq)); return; }
    for (int plane = 0; plane < TAffine.Planes.Length; plane++)
        for (int angle = 1; angle <= 3; angle++)
        {
            var c = ApplyMove(o, plane, angle);
            if (RotCount(c, permIdx, orderIdx, reversed) == rc - 1)
            {
                seq.Add(plane * 4 + angle);
                Dfs(c, permIdx, orderIdx, reversed, rc - 1, seq, results);
                seq.RemoveAt(seq.Count - 1);
            }
        }
}

// Moves-to-solve of orientation o under the metric: count the non-identity Givens rotations of the
// QR of PᵀMP taken in plane order orders[orderIdx] (reversed = decompose the transpose, the M^T route).
static int RotCount(TAffine o, int permIdx, int orderIdx, bool reversed)
{
    long mode = ((long)permIdx * orders.Length + orderIdx) * 2 + (reversed ? 1 : 0);
    long key = (long)o.OrthoPack() * (perms.Length * (long)orders.Length * 2) + mode;
    if (rotMemo.TryGetValue(key, out var cached)) return cached;

    int n = TAffine.N;
    var perm = perms[permIdx];
    var t = new TAffine();
    for (int y = 0; y < n; y++)
        for (int x = 0; x < n; x++)
            t.M[y, x] = o.M[perm[y], perm[x]];
    var angles = t.GetEulerAngles(orders[orderIdx], reversed);
    int c = 0;
    foreach (var a in angles)
        if (TCubie.GetAngle(a[0], a[1]) != 0) c++;

    rotMemo[key] = c;
    return c;
}

