static HashSet<string> AllGreedy(TAffine o, int permIdx, int orderIdx, bool reversed)
{
    // Work copy carries the orientation plus a canonical CORNER position, so the slice (collateral-axis
    // coord) varies as the cubie moves. A centre cubie never changes slice; slice must be real because
    // Correct folds on it.
    var work = new TAffine();
    work.M.Assign(o.M);
    for (int i = 0; i < TAffine.N; i++) work.Origin[i] = -TRubikCube.C;
    var results = new HashSet<string>();
    Dfs(work, permIdx, orderIdx, reversed, RotCount(o, permIdx, orderIdx, reversed), new List<int>(), results);
    return results;
}

static void Dfs(TAffine o, int permIdx, int orderIdx, bool reversed, int rc, List<int> genes, HashSet<string> results)
{
    if (rc == 0)
    {
        var g = new List<int>(genes);
        CorrectGenes(g);
        results.Add(string.Join(" ", g));
        return;
    }
    for (int plane = 0; plane < TAffine.Planes.Length; plane++)
        for (int angle = 1; angle <= 3; angle++)
        {
            var c = ApplyMove(o, plane, angle);
            if (RotCount(c, permIdx, orderIdx, reversed) == rc - 1)
            {
                int axis = FirstAxis(plane);
                int slice = (int)Math.Round(o.Origin[axis] + TRubikCube.C);   // collateral coord (move-invariant)
                genes.Add(new TMove { Plane = plane, Angle = angle, Axis = axis, Slice = slice }.Encode());
                Dfs(c, permIdx, orderIdx, reversed, rc - 1, genes, results);
                genes.RemoveAt(genes.Count - 1);
            }
        }
}

