// Home Origin of the generic frame cubie: coords (0, 1, ..., N-1). Their distances from the centre
// are all distinct (needs Size >= 2N-1), so every axis sits at a distinct distance -> the per-axis
// slices never collide along the whole trajectory (coord value-ranges C±d are disjoint for distinct
// d), which is exactly what Correct needs to tell different-layer manoeuvres apart. null if Size is
// too small. NOTE: several clusters share the orientation-count size, but only the distinct-distance
// one gives non-colliding slices - a repeated-distance cubie (e.g. (0,0,1,2)) collapses to slice 0.
static TVector GenericFrameOrigin()
{
    int n = TAffine.N;
    if (2 * n - 1 > TRubikCube.Size) return null;
    var origin = new TVector(n);
    for (int i = 0; i < n; i++) origin[i] = i - TRubikCube.C;   // coords (0, 1, ..., N-1)
    return origin;
}

