            return $"No orientation-sized cluster at Size = {TRubikCube.Size}. For N = {n} set Size >= {2 * n - 1}, then retry (see Orientation Cluster).";
        var frameCoords = new int[n];
        for (int i = 0; i < n; i++) frameCoords[i] = (int)Math.Round(frameOrigin[i] + TRubikCube.C);

