        sb.AppendLine($"  + plane order (GetOrder)            : {sumOrder}   (+{Pct(sumId, sumOrder):0.0}%)   <- measured");
        sb.AppendLine();
        sb.AppendLine("  reference:");
        sb.AppendLine($"  + axis permutations (N!)            : {sumPerm}   (+{Pct(sumId, sumPerm):0.0}%)");
        sb.AppendLine($"  + transposition (reversed)          : {sumRev}   (+{Pct(sumId, sumRev):0.0}%)");
