public static string Run()
{
    int n = TAffine.N;
    perms = Permutations(n);
    orders = AllOrders();
    rotMemo = new Dictionary<long, int>();
    var orientations = AllOrientations();

    frameOrigin = GenericFrameOrigin(orientations.Count);   // any max-cluster cubie (slice is inert anyway)
    if (frameOrigin == null)
        return $"No orientation-sized cluster at Size = {TRubikCube.Size}. For N = {n} set Size >= {2 * n - 1}, then retry (see Orientation Cluster).";
    var frameCoords = new int[n];
    for (int i = 0; i < n; i++) frameCoords[i] = (int)Math.Round(frameOrigin[i] + TRubikCube.C);

    long sumId = 0, sumOrder = 0, sumPerm = 0, sumRev = 0, sumBoth = 0;
    int gainedOrder = 0, maxDeltaOrder = 0;
    string example = null;
    // Distinct manoeuvres bucketed by length: baseline (standard QR) vs. reachable only via the live
    // axes (perm x order). A shortest path has length <= plane count, so that + 1 sizes the buckets.
    var histId = new int[TAffine.Planes.Length + 1];
    var histExtra = new int[TAffine.Planes.Length + 1];

    foreach (var o in orientations)
    {
        var idSet = AllGreedy(o, 0, 0, false);               // identity perm, standard order = baseline

        var orderUnion = new HashSet<string>(idSet);         // measured: + plane order
        for (int q = 1; q < orders.Length; q++)
            orderUnion.UnionWith(AllGreedy(o, 0, q, false));

        var permUnion = new HashSet<string>(idSet);          // reference: + axis permutations
        for (int p = 1; p < perms.Length; p++)
            permUnion.UnionWith(AllGreedy(o, p, 0, false));

        var revUnion = new HashSet<string>(idSet);           // reference: + transposition
        revUnion.UnionWith(AllGreedy(o, 0, 0, true));

        var bothUnion = new HashSet<string>();               // reference: full perm x order cross
        for (int p = 0; p < perms.Length; p++)
            for (int q = 0; q < orders.Length; q++)
                bothUnion.UnionWith(AllGreedy(o, p, q, false));

        sumId += idSet.Count;
        sumOrder += orderUnion.Count;
        sumPerm += permUnion.Count;
        sumRev += revUnion.Count;
        sumBoth += bothUnion.Count;

        int delta = orderUnion.Count - idSet.Count;
        if (delta > 0)
        {
            gainedOrder++;
            if (delta > maxDeltaOrder) { maxDeltaOrder = delta; example = ExampleExtra(o, idSet, orderUnion); }
        }
        foreach (var s in idSet) histId[Len(s)]++;
        foreach (var s in bothUnion) if (!idSet.Contains(s)) histExtra[Len(s)]++;
    }

    int count = orientations.Count;
    var sb = new StringBuilder();
    sb.AppendLine($"Greedy decomposition diversity  (N = {n})");
    sb.AppendLine($"  cubie orientations (rotation group) : {count}");
    sb.AppendLine($"  axis permutations (N!)              : {perms.Length}");
    sb.AppendLine($"  valid plane orders                  : {orders.Length}");
    sb.AppendLine($"  slice frame (generic cubie, Size {TRubikCube.Size}) : ({string.Join(",", frameCoords)})");
    sb.AppendLine();
    sb.AppendLine($"  baseline (standard QR)              : {sumId}   (avg {sumId / (double)count:0.00} / orientation)");
    sb.AppendLine($"  + plane order (GetOrder)            : {sumOrder}   (+{Pct(sumId, sumOrder):0.0}%)   <- measured");
    sb.AppendLine();
    sb.AppendLine("  reference:");
    sb.AppendLine($"  + axis permutations (N!)            : {sumPerm}   (+{Pct(sumId, sumPerm):0.0}%)");
    sb.AppendLine($"  + transposition (reversed)          : {sumRev}   (+{Pct(sumId, sumRev):0.0}%)");
    sb.AppendLine($"  + perms x order (full cross)        : {sumBoth}   (+{Pct(sumId, sumBoth):0.0}%)");
    sb.AppendLine();
    sb.AppendLine($"  orientations where order adds       : {gainedOrder} / {count}");
    sb.AppendLine($"  max extra on one orientation (order): {maxDeltaOrder}");
    if (example != null)
        sb.AppendLine($"  example only reachable via order    : {example}");
    sb.AppendLine();
    sb.AppendLine("  distinct manoeuvres by length (moves after Correct):");
    sb.AppendLine("    length   identity   extra(both)");
    for (int L = 0; L < histId.Length; L++)
        if (histId[L] > 0 || histExtra[L] > 0)
            sb.AppendLine($"    {L,6}   {histId[L],8}   {histExtra[L],10}");
    return sb.ToString();
}

