    int gainedMode = 0, maxDeltaMode = 0;
    string example = null;
    var histId = new int[TAffine.Planes.Length + 1];
    var histExtra = new int[TAffine.Planes.Length + 1];   // extra reachable via perm x mode (both live axes)

    foreach (var o in orientations)
    {
        var idSet = AllGreedy(o, 0, 0);                      // identity perm, mode 0 (all-pod) = baseline

        var modeUnion = new HashSet<string>(idSet);          // measured: + mixed reduction (pod/nad-L)
        for (int m = 1; m < modeCount; m++)
            modeUnion.UnionWith(AllGreedy(o, 0, m));

        var permUnion = new HashSet<string>(idSet);          // reference: + axis permutations
        for (int p = 1; p < perms.Length; p++)
            permUnion.UnionWith(AllGreedy(o, p, 0));

        var bothUnion = new HashSet<string>();               // reference: full perm x mode cross
        for (int p = 0; p < perms.Length; p++)
            for (int m = 0; m < modeCount; m++)
                bothUnion.UnionWith(AllGreedy(o, p, m));

        sumId += idSet.Count;
        sumMode += modeUnion.Count;
        sumPerm += permUnion.Count;
        sumBoth += bothUnion.Count;

        int delta = modeUnion.Count - idSet.Count;
        if (delta > 0)
        {
            gainedMode++;
            if (delta > maxDeltaMode) { maxDeltaMode = delta; example = ExampleExtra(o, idSet, modeUnion); }
        }
        foreach (var s in idSet) histId[Len(s)]++;
        foreach (var s in bothUnion) if (!idSet.Contains(s)) histExtra[Len(s)]++;
    }

    int count = orientations.Count;
    var sb = new StringBuilder();
    sb.AppendLine($"Greedy decomposition diversity  (N = {n})");
    sb.AppendLine($"  cubie orientations (rotation group) : {count}");
    sb.AppendLine($"  axis permutations (N!)              : {perms.Length}");
    sb.AppendLine($"  reduction modes (2^P, pod/nad-L)    : {modeCount}");
    sb.AppendLine($"  slice frame (generic cubie, Size {TRubikCube.Size}) : ({string.Join(",", frameCoords)})");
    sb.AppendLine();
    sb.AppendLine($"  baseline (standard QR, all-pod)     : {sumId}   (avg {sumId / (double)count:0.00} / orientation)");
