    sb.AppendLine();
    sb.AppendLine("  reference:");
    sb.AppendLine($"  + axis permutations (N!)            : {sumPerm}   (+{Pct(sumId, sumPerm):0.0}%)");
    sb.AppendLine($"  + perms x mode (full cross)         : {sumBoth}   (+{Pct(sumId, sumBoth):0.0}%)");
    sb.AppendLine();
    sb.AppendLine($"  orientations where mode adds        : {gainedMode} / {count}");
    sb.AppendLine($"  max extra on one orientation (mode) : {maxDeltaMode}");
