// Home Origin of any cubie whose cluster size equals orientCount: a max cluster, so the cubie reaches
// every orientation. null if no such cluster at the current Size (too small). The exact cubie does not
// matter - the slice turns out inert for the distinct count (it is a deterministic function of the
// (plane,angle) trajectory and invariant along same-plane runs, so it changes no Correct fold and adds
// no distinction), which is why any such frame - and even Slice = 0 - gives identical results.
static TVector GenericFrameOrigin(int orientCount)
{
    var cube = new TRubikCube();
    var sizeByCluster = new Dictionary<int, int>();
    foreach (var cubie in cube.Cubies)
    {
        sizeByCluster.TryGetValue(cubie.ClusterIndex, out var c);
        sizeByCluster[cubie.ClusterIndex] = c + 1;
    }
    foreach (var cubie in cube.Cubies)
        if (sizeByCluster[cubie.ClusterIndex] == orientCount)
            return cubie.Transform.Origin.Clone();
    return null;
}

// All reachable cubie orientations, generated by closing the identity under every quarter-turn.

