static void Dfs(TAffine o, int permIdx, int modeMask, int rc, List<int> genes, HashSet<string> results)
{
    if (rc == 0)
    {
        if (o.OrthoPack() == identityPack)   // solve-check: mixed modes can reach rc==0 with M != I
        {
            var g = new List<int>(genes);
            CorrectGenes(g);
            results.Add(string.Join(" ", g));
        }
        return;
    }
    for (int plane = 0; plane < TAffine.Planes.Length; plane++)
        for (int angle = 1; angle <= 3; angle++)
        {
            var c = ApplyMove(o, plane, angle);
            if (RotCount(c, permIdx, modeMask) == rc - 1)
            {
                int axis = FirstAxis(plane);
                int slice = (int)Math.Round(o.Origin[axis] + TRubikCube.C);   // collateral coord (move-invariant)
                genes.Add(new TMove { Plane = plane, Angle = angle, Axis = axis, Slice = slice }.Encode());
                Dfs(c, permIdx, modeMask, rc - 1, genes, results);
                genes.RemoveAt(genes.Count - 1);
            }
        }
}

// Moves-to-solve of orientation o under the metric: permute axes by perms[permIdx] (PᵀMP), then reduce
// with a per-plane mixed Givens - bit p of modeMask picks nad-L (zero the SUPER-diagonal [a1,a2] with a
// left rotation, pivot A[a2,a2]) instead of pod (zero the SUB-diagonal [a2,a1], pivot A[a1,a1]). Both are
// left multiplications (real cube-move rotations). Count the non-identity rotations; a mode that replaces
// an earlier zero may never reach I - the greedy's solve-check discards those paths.
static int RotCount(TAffine o, int permIdx, int modeMask)
{
    int planeCount = TAffine.Planes.Length;
    long span = perms.Length * (long)(1 << planeCount);
    long key = (long)o.OrthoPack() * span + permIdx * (long)(1 << planeCount) + modeMask;
    if (rotMemo.TryGetValue(key, out var cached)) return cached;

    int n = TAffine.N;
    var perm = perms[permIdx];
    var A = new TMatrix(n, n);
    for (int y = 0; y < n; y++)
        for (int x = 0; x < n; x++)
            A[y, x] = o.M[perm[y], perm[x]];

    int c = 0;
    for (int p = 0; p < planeCount; p++)
    {
        int a1 = TAffine.Planes[p][0], a2 = TAffine.Planes[p][1];
        float a, b;
        if ((modeMask & (1 << p)) == 0) { a = A[a1, a1]; b = A[a2, a1]; }   // pod: zero sub-diagonal [a2,a1]
        else                            { a = A[a2, a2]; b = -A[a1, a2]; }  // nad-L: zero super-diagonal [a1,a2]
        float r = (float)Math.Sqrt(a * a + b * b);
        if (r < 0.1f) continue;                                            // pivot ~ 0 -> identity rotation
        float cos = a / r, sin = b / r;
        A.Rotate(a1, a2, cos, -sin);
        if (TCubie.GetAngle(cos, sin) != 0) c++;
    }
    rotMemo[key] = c;
    return c;
}

static TAffine ApplyMove(TAffine o, int plane, int angle)
{
    var c = o.Clone();
    var pa = TAffine.Planes[plane];
    var rot = TCubie.SetAngle(angle);
    c.Rotate(pa[0], pa[1], rot.X, rot.Y);
    return c;

