// Empirical check: every mode-generated manoeuvre, applied to a real cube (target cubie set to the
// orientation, moves realised with the real slice = target's current layer), should actually SOLVE the
// target. Also hashes the whole-cube effect to count distinct macro-moves (dedup by real effect, not by
// Correct string) - so we see how many of the length-4/5 sequences are genuinely different manoeuvres.
// The cube is restored after each manoeuvre by applying it in reverse (cheap), so it is reset per
// orientation, not per manoeuvre.
public static string Verify()
{
    int n = TAffine.N;
    perms = Permutations(n);
    orders = AllOrders();
    rotMemo = new Dictionary<long, int>();
    identityPack = new TAffine().OrthoPack();
    int modeCount = 1 << TAffine.Planes.Length;
    var orientations = AllOrientations();

    var cube = new TRubikCube();
    int targetIndex = 0;                 // any cubie; its position is just the slice frame
    var tgt = cube.Cubies[targetIndex];

    long total = 0, solved = 0, stringDistinct = 0;
    var effects = new HashSet<string>();

    foreach (var o in orientations)
    {
        var manoeuvres = new HashSet<string>();
        for (int m = 0; m < modeCount; m++)
            manoeuvres.UnionWith(AllGreedy(o, 0, 0, false, m));

        foreach (var cb in cube.Cubies) cb.State = 0;              // reset the cube to solved
        tgt.Transform.M.Assign(o.M);                              // set the target orientation to o
        tgt.Rotate(TAffine.Planes[0], TCubie.SetAngle(0));        // no-op rotate: invalidate State, keep M/pos

        foreach (var man in manoeuvres)
        {
            if (man.Length == 0) continue;                        // identity orientation -> no manoeuvre
            stringDistinct++; total++;

            var applied = new List<int[]>();
            foreach (var code in man.Split(' '))
            {
                var mv = TMove.Decode(int.Parse(code));
                int sl = tgt.GetPos(mv.Axis);                     // real slice: the target's current layer
                LocalTurn(cube, mv.Plane, mv.Angle, mv.Axis, sl);
                applied.Add(new[] { mv.Plane, mv.Angle, mv.Axis, sl });
            }

            if (tgt.State == 0) solved++;
            effects.Add(o.OrthoPack() + "|" + CubeHash(cube));

            for (int i = applied.Count - 1; i >= 0; i--)          // restore: apply the manoeuvre in reverse
