    sb.AppendLine($"  mode manoeuvres (Correct-distinct)  : {stringDistinct}");
    sb.AppendLine($"  verified to SOLVE the target        : {solved} / {total}   ({(total == 0 ? 0 : 100.0 * solved / total):0.00}%)");
    sb.AppendLine($"  distinct macro-moves (whole-cube fx): {effects.Count}");
    if (stringDistinct > 0)
