    if (stringDistinct > 0)
        sb.AppendLine($"  Correct-strings sharing an effect   : {stringDistinct - effects.Count}   ({100.0 * (stringDistinct - effects.Count) / stringDistinct:0.0}%)");
    return sb.ToString();
}

