# -*- coding: utf-8 -*-
import json, re, sys
path = r'C:\Users\robert.swita\.claude\projects\C---Moje-Dane--Moje-Programy-Visual-C--RubikCubeND\f2be91dc-fb0a-479e-bb5b-f5756624ca6b.jsonl'
dst  = r'C:\_Moje Dane\_Moje Programy\Visual C#\RubikCubeND\Docs\Konwersacja_RubikND.md'
DRY = '--write' not in sys.argv

def text_of(content):
    if isinstance(content, str): return content
    if isinstance(content, list):
        return "\n".join(b.get('text','') for b in content if isinstance(b,dict) and b.get('type')=='text')
    return ""
SKIP=('<system-reminder>','This session is being continued','<command-name>','<command-message>',
      '<local-command-stdout>','Caveat:','<command-args>','[Request interrupted','<system>')
def is_noise(t):
    s=t.strip()
    if not s: return True
    return any(s.startswith(m) for m in SKIP)

turns=[]
with open(path,encoding='utf-8') as f:
    for line in f:
        line=line.strip()
        if not line: continue
        try: o=json.loads(line)
        except: continue
        t=o.get('type')
        if t not in ('user','assistant'): continue
        msg=o.get('message',{})
        if not isinstance(msg,dict): continue
        txt=text_of(msg.get('content'))
        txt=re.sub(r'<system-reminder>.*?</system-reminder>','',txt,flags=re.S).strip()
        if t=='user':
            if is_noise(txt): continue
            if not txt: continue
            turns.append(('user',txt))
        else:
            if txt.strip(): turns.append(('assistant',txt.strip()))

# merge consecutive same-role
merged=[]
for role,txt in turns:
    if merged and merged[-1][0]==role: merged[-1]=(role, merged[-1][1]+"\n\n"+txt)
