static void Dfs(TAffine o, int permIdx, int orderIdx, bool reversed, int modeMask, int rc, List<int> genes, HashSet<string> results)
{
    if (rc == 0)
    {
        if (o.OrthoPack() == identityPack)   // solve-check: mixed modes can reach rc==0 with M != I
        {
            var g = new List<int>(genes);
            CorrectGenes(g);
            results.Add(string.Join(" ", g));
        }
        return;
    }
    for (int plane = 0; plane < TAffine.Planes.Length; plane++)
        for (int angle = 1; angle <= 3; angle++)
        {
            var c = ApplyMove(o, plane, angle);
            if (RotCount(c, permIdx, orderIdx, reversed, modeMask) == rc - 1)
            {
                genes.Add(new TMove { Plane = plane, Angle = angle, Axis = FirstAxis(plane), Slice = 0 }.Encode());
                Dfs(c, permIdx, orderIdx, reversed, modeMask, rc - 1, genes, results);
                genes.RemoveAt(genes.Count - 1);
            }
        }
}

// Moves-to-solve of orientation o under a metric variant: permute axes by perms[permIdx] (PᵀMP), optionally
// transpose (reversed), then reduce plane-by-plane in orders[orderIdx] with a mixed Givens - bit p of mode
// picks nad-L (zero SUPER-diagonal [a1,a2], pivot A[a2,a2]) vs pod (zero SUB-diagonal [a2,a1], pivot
// A[a1,a1]); both are left multiplications. Count non-identity rotations. mode=0,order=0,reversed=false
// reproduces the standard QR baseline (built-in sanity check).

