// Moves-to-solve of an orientation under a mixed-Givens "mode": reduce the matrix plane-by-plane in
// natural order; bit p of modeMask picks nad-L (zero the SUPER-diagonal [a1,a2], pivot A[a2,a2],
// b = -A[a1,a2]) vs pod (zero the SUB-diagonal [a2,a1], pivot A[a1,a1]) - both are LEFT rotations, i.e.
// real cube moves. Counts the non-identity rotations. modeMask == 0 reproduces the standard QR
// baseline. DESTRUCTIVE: consumes the passed matrix, so callers hand it a throw-away clone.
static int RotCountMode(TMatrix A, int modeMask)
{
    int c = 0;
    for (int p = 0; p < TAffine.Planes.Length; p++)
    {
        int a1 = TAffine.Planes[p][0], a2 = TAffine.Planes[p][1];
        float a, b;
        if ((modeMask & (1 << p)) == 0) { a = A[a1, a1]; b = A[a2, a1]; }   // pod  (zero sub-diagonal)
        else                            { a = A[a2, a2]; b = -A[a1, a2]; }  // nad-L (zero super-diagonal)
        float r = (float)Math.Sqrt(a * a + b * b);
        if (r < 0.1f) continue;                                            // pivot ~ 0 -> identity rotation
        float cos = a / r, sin = b / r;
        A.Rotate(a1, a2, cos, -sin);
        if (TCubie.GetAngle(cos, sin) != 0) c++;
    }
    return c;
}

// mode moves-to-solve of orientation M after applying cube move (plane, angle). Clones the small n x n
// matrix (not the whole cubie) and left-rotates it exactly as Turn rotates a cubie, so the greedy's
// prediction matches the real move; the clone leaves M intact for the sibling candidates.
static int RotCountModeAfter(TMatrix M, int plane, int angle, int modeMask)
{
    var A = (TMatrix)M.Clone();
    var pa = TAffine.Planes[plane];
    var rot = TCubie.SetAngle(angle);
    A.Rotate(pa[0], pa[1], rot.X, rot.Y);
    return RotCountMode(A, modeMask);
}

// Greedy solve of the host-designated active cubie under a mixed-Givens mode, on a lightweight copy of
// just that cubie (deep Transform, shared geometry) - no full-cube clone, since only its orientation is
// needed. At each step pick a random cube move (plane + 90/180/270) that lowers the mode moves-to-solve
// by one, realize it with a random valid axis, record its code and rotate the copy - until the
// orientation is the identity. modeMask == 0 is the standard shortest-solve; mixed modes trace LONGER
// (macro-move) paths that still terminate at the identity. Returns null when the mode gets stuck (its
// metric hits 0 with M != I, or no progress move exists) - the caller redraws a fresh mode.
public List<int> GetSolveSeq(int modeMask)
{
    var c = ActiveCubie.Copy();        // just the cubie - no full-cube clone
    var seq = new List<int>();
    while (c.State != 0)          // true solve-check (identity orientation), metric-independent
    {
        int rc = RotCountMode((TMatrix)c.Transform.M.Clone(), modeMask);
        var cand = new List<int[]>();
        for (int plane = 0; plane < TAffine.Planes.Length; plane++)
            for (int angle = 1; angle <= 3; angle++)   // quarter-turns: 1/2/3 = 90/180/270
                if (RotCountModeAfter(c.Transform.M, plane, angle, modeMask) == rc - 1)
                    cand.Add(new[] { plane, angle });
        if (cand.Count == 0) return null;                    // mode stuck -> caller redraws
        var pick = cand[TChromosome.Rnd.Next(cand.Count)];
        var pa = TAffine.Planes[pick[0]];
        c.Rotate(pa, TCubie.SetAngle(pick[1]));
        int axis = TChromosome.Rnd.Next(TAffine.N);          // any axis not in the plane (collateral only)
        while (axis == pa[0] || axis == pa[1])
            axis = (axis + 1) % TAffine.N;
        seq.Add(new TMove { Plane = pick[0], Angle = pick[1], Axis = axis, Slice = c.GetPos(axis) }.Encode());
    }
    return seq;
}

