// needed. At each step pick a random cube move (plane + 90/180/270) that lowers the mode moves-to-solve
// by one, realize it with a random valid axis, record its code and rotate the copy - until the
// orientation is the identity. modeMask == 0 is the standard shortest-solve; mixed modes trace LONGER
// (macro-move) paths that still terminate at the identity. Returns null when the mode gets stuck (its
// metric hits 0 with M != I, or no progress move exists) - the caller redraws a fresh mode.
public List<int> GetSolveSeq(int modeMask)
{
    var c = ActiveCubie.Copy();        // just the cubie - no full-cube clone
    var seq = new List<int>();
    while (c.State != 0)          // true solve-check (identity orientation), metric-independent
    {
        int rc = RotCountMode((TMatrix)c.Transform.M.Clone(), modeMask);
        var cand = new List<int[]>();
        for (int plane = 0; plane < TAffine.Planes.Length; plane++)
            for (int angle = 1; angle <= 3; angle++)   // quarter-turns: 1/2/3 = 90/180/270
                if (RotCountModeAfter(c.Transform.M, plane, angle, modeMask) == rc - 1)
                    cand.Add(new[] { plane, angle });
        if (cand.Count == 0) return null;                    // mode stuck -> caller redraws
        var pick = cand[TChromosome.Rnd.Next(cand.Count)];
        var pa = TAffine.Planes[pick[0]];
        c.Rotate(pa, TCubie.SetAngle(pick[1]));
        int axis = TChromosome.Rnd.Next(TAffine.N);          // any axis not in the plane (collateral only)
        while (axis == pa[0] || axis == pa[1])
            axis = (axis + 1) % TAffine.N;
        seq.Add(new TMove { Plane = pick[0], Angle = pick[1], Axis = axis, Slice = c.GetPos(axis) }.Encode());
    }
    return seq;
}

