static double Pct(long baseVal, long total) => baseVal == 0 ? 0 : 100.0 * (total - baseVal) / baseVal;

public static string Run()
{
    int n = TAffine.N;
    perms = Permutations(n);
    orders = AllOrders();
    rotMemo = new Dictionary<long, int>();
    identityPack = new TAffine().OrthoPack();
    var orientations = AllOrientations();
    int modeCount = 1 << TAffine.Planes.Length;

    long sumId = 0, sumPerm = 0, sumOrder = 0, sumRev = 0, sumMode = 0, sumAll = 0;
    int gainedAll = 0;
    string example = null;
    int P = TAffine.Planes.Length;
    var histId = new int[P + 1];                           // baseline manoeuvres by length
    var histPerm = new int[P + 1];                         // EXTRA (vs baseline) by length, per axis
    var histOrder = new int[P + 1];
    var histRev = new int[P + 1];
    var histMode = new int[P + 1];

    foreach (var o in orientations)
    {
        var idSet = AllGreedy(o, 0, 0, false, 0);            // all knobs standard = baseline

        var permU = new HashSet<string>(idSet);
        for (int p = 1; p < perms.Length; p++) permU.UnionWith(AllGreedy(o, p, 0, false, 0));

        var orderU = new HashSet<string>(idSet);
        for (int q = 1; q < orders.Length; q++) orderU.UnionWith(AllGreedy(o, 0, q, false, 0));

        var revU = new HashSet<string>(idSet);
        revU.UnionWith(AllGreedy(o, 0, 0, true, 0));

        var modeU = new HashSet<string>(idSet);
        for (int m = 1; m < modeCount; m++) modeU.UnionWith(AllGreedy(o, 0, 0, false, m));

        var allU = new HashSet<string>(permU);              // union of the individual axes (no cross synergy)
        allU.UnionWith(orderU); allU.UnionWith(revU); allU.UnionWith(modeU);

        sumId += idSet.Count; sumPerm += permU.Count; sumOrder += orderU.Count;
        sumRev += revU.Count; sumMode += modeU.Count; sumAll += allU.Count;

        if (allU.Count > idSet.Count)
        {
            gainedAll++;
            if (example == null) example = ExampleExtra(o, idSet, modeU.Count > permU.Count ? modeU : allU);
        }
        foreach (var s in idSet) histId[Len(s)]++;
        foreach (var s in permU)  if (!idSet.Contains(s)) histPerm[Len(s)]++;
        foreach (var s in orderU) if (!idSet.Contains(s)) histOrder[Len(s)]++;
        foreach (var s in revU)   if (!idSet.Contains(s)) histRev[Len(s)]++;
        foreach (var s in modeU)  if (!idSet.Contains(s)) histMode[Len(s)]++;
    }

    int count = orientations.Count;
    var sb = new StringBuilder();
    sb.AppendLine($"Greedy decomposition diversity  (N = {n}, Size = {TRubikCube.Size})");
    sb.AppendLine($"  cubie orientations (rotation group) : {count}");
    sb.AppendLine($"  axis permutations (N!)              : {perms.Length}");
    sb.AppendLine($"  valid plane orders                  : {orders.Length}");
    sb.AppendLine($"  reduction modes (2^P, pod/nad-L)    : {modeCount}");
    sb.AppendLine();
    sb.AppendLine($"  baseline (standard QR)              : {sumId}   (avg {sumId / (double)count:0.00} / orientation)");
    sb.AppendLine();
    sb.AppendLine("  each axis alone (vs baseline):");
    sb.AppendLine($"  + axis permutations (perm)          : {sumPerm}   (+{Pct(sumId, sumPerm):0.0}%)");
    sb.AppendLine($"  + plane order (order)               : {sumOrder}   (+{Pct(sumId, sumOrder):0.0}%)");
    sb.AppendLine($"  + transposition (reversed)          : {sumRev}   (+{Pct(sumId, sumRev):0.0}%)");
    sb.AppendLine($"  + mixed reduction (mode, pod/nad-L) : {sumMode}   (+{Pct(sumId, sumMode):0.0}%)");
    sb.AppendLine();
    sb.AppendLine($"  combined (union of the four axes)   : {sumAll}   (+{Pct(sumId, sumAll):0.0}%)");
    sb.AppendLine($"  orientations where any axis adds    : {gainedAll} / {count}");
    if (example != null)
        sb.AppendLine($"  example only reachable off-baseline : {example}");
    sb.AppendLine();
    sb.AppendLine("  manoeuvres by length  (baseline count, then EXTRA vs baseline per axis):");
    sb.AppendLine("    length  baseline    perm   order  reversd    mode");
    for (int L = 0; L < histId.Length; L++)
        if (histId[L] > 0 || histPerm[L] > 0 || histOrder[L] > 0 || histRev[L] > 0 || histMode[L] > 0)
            sb.AppendLine($"    {L,6}  {histId[L],8}  {histPerm[L],6}  {histOrder[L],6}  {histRev[L],7}  {histMode[L],6}");
    return sb.ToString();
}

