// increasing-index order). Used only for the UI "Cluster No / Count" label. Computed once, lazily.
private int maxClusterIndex = -1;
public int MaxClusterIndex
{
    get
    {
        if (maxClusterIndex < 0)
            foreach (var cubie in Cubies)
                if (cubie.ClusterIndex > maxClusterIndex) maxClusterIndex = cubie.ClusterIndex;
        return maxClusterIndex;
    }
}

