        int i = 0;
        foreach (var cubie in Cubies)
            cubie.State = value[i++];
    }
}

public List<TCubie> SelectSlice(TMove move)
{
    var selection = new List<TCubie>();
    //var planeAxes = TAffine.Planes[move.Plane];
    //for (int segNo = 0; segNo < Size; segNo++)
    //    for (int i = 0; i < Size; i++)
