// Per-face alpha for an unsolved cubie that read well at N=3 (faceCount 6). The shader gets the
// final alpha per instance and stays oblivious to the geometry - the layer compensation lives here.
public static float BaseUnsolvedAlpha = 0.1f;

public override float Transparency {
    get {
        if (State == 0)
            base.Transparency = 1;                          // solved: opaque
        else
        {
            // A hypercube has faceCount = P * 2^(N-2) faces, all stacking in the WBOIT revealage
            // (product of 1-alpha over the layers). A fixed per-face alpha makes high-N cubies pile
            // up to near-opaque. Scale alpha so the NET revealage stays what N=3 had: revealage
            // (1-a)^faceCount constant => a = 1 - (1-BaseUnsolvedAlpha)^(6 / faceCount). Any true
            // layer count L proportional to faceCount cancels, so this holds regardless of L.
            int faceCount = TAffine.Planes.Length * (1 << TAffine.N - 2);
            base.Transparency = 1f - (float)Math.Pow(1 - BaseUnsolvedAlpha, 6.0 / faceCount);
        }
        return base.Transparency;
    }
}

