136	            var orientations = AllOrientations();
137	
138	            var cube = new TRubikCube();
139	            // Generic target: a cubie whose distances from the centre are all distinct (trivial stabilizer),
140	            // so no two manoeuvres collapse to the same whole-cube effect by position symmetry. Needs Size >= 2N-1.
141	            int targetIndex = -1;
142	            foreach (var cubie in cube.Cubies)
143	            {
144	                var org = cubie.Transform.Origin;
145	                bool distinct = true;
146	                for (int i = 0; i < n && distinct; i++)
147	                    for (int j = i + 1; j < n; j++)
148	                        if (Math.Abs(Math.Abs(org[i]) - Math.Abs(org[j])) < 0.5f) { distinct = false; break; }
149	                if (distinct) { targetIndex = cubie.StartIndex; break; }
150	            }
151	            if (targetIndex < 0)
152	                return $"No generic (distinct-distance) cubie at Size = {TRubikCube.Size}. Set Size >= {2 * n - 1} (see Orientation Cluster), then retry.";
153	            var tgt = cube.Cubies[targetIndex];
154	            var targetCoords = string.Join(",", tgt.Position);
155	
156	            long total = 0, solved = 0;
157	            long strId = 0, strPerm = 0, strOrder = 0, strMode = 0, strAll = 0;
158	            long effId = 0, effPerm = 0, effOrder = 0, effMode = 0, effAll = 0;
159	
160	            foreach (var o in orientations)
161	            {
162	                var idSet = AllGreedy(o, 0, 0, false, 0);
163	                var permU = new HashSet<string>(idSet);
164	                for (int p = 1; p < perms.Length; p++) permU.UnionWith(AllGreedy(o, p, 0, false, 0));
165	                var orderU = new HashSet<string>(idSet);
166	                for (int q = 1; q < orders.Length; q++) orderU.UnionWith(AllGreedy(o, 0, q, false, 0));
167	                var modeU = new HashSet<string>(idSet);
168	                for (int m = 1; m < modeCount; m++) modeU.UnionWith(AllGreedy(o, 0, 0, false, SpreadLeft(m)));
169	                var allU = new HashSet<string>(permU);
170	                allU.UnionWith(orderU); allU.UnionWith(modeU);
171	
172	                foreach (var cb in cube.Cubies) cb.State = 0;              // reset the cube to solved
173	                tgt.Transform.M.Assign(o.M);                              // set the target orientation to o
174	                tgt.Rotate(TAffine.Planes[0], TCubie.SetAngle(0));        // no-op rotate: invalidate State, keep M/pos
175	
176	                var manEffect = new Dictionary<string, string>();         // manoeuvre -> real whole-cube effect
177	                foreach (var man in allU)
178	                {
179	                    if (man.Length == 0) continue;
180	                    total++;
181	                    var applied = new List<TMove>();
182	                    foreach (var code in man.Split(' '))
183	                    {
184	                        var mv = TMove.Decode(int.Parse(code));
185	                        mv.Slice = tgt.GetPos(mv.Axis);                   // real slice: the target's current layer
