// real cube moves. Counts the non-identity rotations. modeMask == 0 reproduces the standard QR
// baseline. DESTRUCTIVE: consumes the passed matrix, so callers hand it a throw-away clone.
static int RotCountMode(TMatrix A, int modeMask)
{
    int c = 0;
    for (int p = 0; p < TAffine.Planes.Length; p++)
    {
        int a1 = TAffine.Planes[p][0], a2 = TAffine.Planes[p][1];
        float a, b;
        if ((modeMask & (1 << p)) == 0) { a = A[a1, a1]; b = A[a2, a1]; }   // pod  (zero sub-diagonal)
        else                            { a = A[a2, a2]; b = -A[a1, a2]; }  // nad-L (zero super-diagonal)
        float r = (float)Math.Sqrt(a * a + b * b);
        if (r < 0.1f) continue;                                            // pivot ~ 0 -> identity rotation
        float cos = a / r, sin = b / r;
        A.Rotate(a1, a2, cos, -sin);
        if (TCubie.GetAngle(cos, sin) != 0) c++;
    }
    return c;

}

