// Moves-to-solve of an orientation under a mixed-Givens "mode": reduce the matrix plane-by-plane in
// natural order with a per-plane strategy packed 2 bits per plane in modeMask (base-4): 0=pod-L,
// 1=nad-L, 2=pod-R, 3=nad-R. pod/nad zero the SUB- vs SUPER-diagonal; L/R = row op (left mult, Rotate,
// -sin) vs column op (right mult, RotatePost, +sin). A right op in the reduction still yields a real
// cube move in the solving sequence (L*M*R = I => M^-1 = R*L). Counts the non-identity rotations.
// modeMask == 0 reproduces the standard QR baseline. DESTRUCTIVE: consumes the passed matrix, so
// callers hand it a throw-away clone. (Mirrors the effect-verified TGreedyDiversity.RotCount.)
static int RotCountMode(TMatrix A, int modeMask)
{
    int c = 0;
    for (int p = 0; p < TAffine.Planes.Length; p++)
    {
        int a1 = TAffine.Planes[p][0], a2 = TAffine.Planes[p][1];
        int strat = (modeMask >> (2 * p)) & 3;         // 0=pod-L 1=nad-L 2=pod-R 3=nad-R
        float a, b;
        switch (strat)
        {
            case 0:  a = A[a1, a1]; b =  A[a2, a1]; break;   // pod-L: zero sub-diag [a2,a1] (row op)
            case 1:  a = A[a2, a2]; b = -A[a1, a2]; break;   // nad-L: zero super-diag [a1,a2] (row op)
            case 2:  a = A[a2, a2]; b = -A[a2, a1]; break;   // pod-R: zero sub-diag [a2,a1] (col op)
            default: a = A[a1, a1]; b =  A[a1, a2]; break;   // nad-R: zero super-diag [a1,a2] (col op)
        }
        float r = (float)Math.Sqrt(a * a + b * b);
        if (r < 0.1f) continue;                                            // pivot ~ 0 -> identity rotation
        float cos = a / r, sin = b / r;
        if (strat < 2) A.Rotate(a1, a2, cos, -sin);        // left: row op, -sin
        else           A.RotatePost(a1, a2, cos, sin);     // right: col op, +sin
        if (TCubie.GetAngle(cos, sin) != 0) c++;
    }
    return c;

