// N>=4 the full perm x order x strategy composite is ~30M+ AllGreedy calls - sample instead.
// Fresh random draw each run (no fixed seed), so running a few times gives independent traces.
bool sampled = n >= 4;
int sampleOrients = 20, sampleStrats = 512;
int[] strat;
if (sampled)
{
    var rnd = new Random();
    var idx = new List<int>();
    for (int i = 0; i < orientations.Count; i++) idx.Add(i);
    for (int i = idx.Count - 1; i > 0; i--) { int j = rnd.Next(i + 1); (idx[i], idx[j]) = (idx[j], idx[i]); }
    var pick = new List<TAffine>();
    for (int i = 0; i < sampleOrients && i < idx.Count; i++) pick.Add(orientations[idx[i]]);
    orientations = pick;
    var sset = new HashSet<int> { 0 };                 // always include baseline strategy 0
    while (sset.Count < sampleStrats && sset.Count < stratCount) sset.Add(rnd.Next(stratCount));
    strat = new int[sset.Count]; sset.CopyTo(strat);
}
else
{
    strat = new int[stratCount];
    for (int i = 0; i < stratCount; i++) strat[i] = i;
}

