int stall = 0;
int draws = 0, stuck = 0, dupes = 0;                     // telemetry: why the pool ends up the size it is
var lenHist = new SortedDictionary<int, int>();          // accepted-seed length distribution
var modeContrib = new HashSet<int>();                    // distinct modes that landed >=1 accepted seed
while (slots.Count < target)
{
    int mode = TChromosome.Rnd.Next(modeSpace);
    draws++;
    var seq = GetSolveSeq(mode);                          // greedy under a random mixed-Givens mode
    if (seq == null) { stuck++; if (++stall > 32 + 8 * slots.Count) break; continue; }  // stuck -> redraw
    if (seq.Count == 0) break;                            // cubie already solved -> no seeds
    var moves = seq.ToArray();
    if (seen.Add(string.Join(",", moves)))
    {
        slots.Add(moves); stall = 0;
        lenHist.TryGetValue(moves.Length, out int hc); lenHist[moves.Length] = hc + 1;
        modeContrib.Add(mode);
    }
    else
    {
        dupes++;
        if (++stall > 32 + 8 * slots.Count) break;        // long run with no new manoeuvre: exhausted
    }
}

// mode census: rc0 (mode moves-to-solve) of THIS cubie under each of the 2^P modes. Path length
// always equals rc0, so this is the macro-move potential of the cubie itself, independent of the
// sampling loop. All rc0 == minimal => mode is degenerate for this (shallow) cubie; a spread means
// deeper orientations that mixed modes inflate into genuine macro-moves.
var rc0Hist = new SortedDictionary<int, int>();
for (int mode = 0; mode < modeSpace; mode++)
{
    int r = RotCountMode((TMatrix)ActiveCubie.Transform.M.Clone(), mode);
    rc0Hist.TryGetValue(r, out int hc); rc0Hist[r] = hc + 1;
}

