    // N>=4 the full perm x order(P!) x strategy composite is enormous - sample orientations and orders
    // (and strategies if sampleStrats < stratCount). Fresh random draw each run, so re-running gives
    // independent traces. orders is now ALL P!, so sampling it is essential at N=4 (720 orders).
    bool sampled = n >= 4;
    int sampleOrients = 5, sampleStrats = stratCount, sampleOrders = 24;
    int[] strat;
    if (sampled)
    {
        var rnd = new Random();
        orientations = SamplePick(orientations, sampleOrients, rnd);
        if (orders.Length > sampleOrders) orders = SampleOrders(orders, sampleOrders, rnd);
        if (sampleStrats < stratCount)
        {
            var sset = new HashSet<int> { 0 };             // always include baseline strategy 0
            while (sset.Count < sampleStrats) sset.Add(rnd.Next(stratCount));
            strat = new int[sset.Count]; sset.CopyTo(strat);
        }
        else { strat = new int[stratCount]; for (int i = 0; i < stratCount; i++) strat[i] = i; }
    }
    else
    {
        strat = new int[stratCount];
        for (int i = 0; i < stratCount; i++) strat[i] = i;
    }

    long sumId = 0, sumModeLR = 0, sumCrossPerm = 0, sumCrossOrder = 0, sumComposite = 0, sumCompositeP = 0;
    int P = TAffine.Planes.Length;
    var histId = new int[P + 1];                           // baseline manoeuvres by length
    var histModeLR = new int[P + 1];                       // strategy alone (4^P, perm0 order0), EXTRA vs base
    var histCrossPerm = new int[P + 1];                    // strategy x perm, EXTRA vs base
    var histCrossOrder = new int[P + 1];                   // strategy x order, EXTRA vs base
    var histComposite = new int[P + 1];                    // strategy x perm x order (full), EXTRA vs base

    foreach (var o in orientations)
    {
        if (sampled) rotMemo.Clear();                       // bound memory: variants don't carry across orientations here

        var idSet = AllGreedy(o, 0, 0, false, 0);           // baseline (standard QR)

        var modeLRU = new HashSet<string>(idSet);           // strategy alone: sampled 4^P at perm0, order0
        foreach (int m in strat) if (m != 0) modeLRU.UnionWith(AllGreedy(o, 0, 0, false, m));

        var crossPerm = new HashSet<string>(modeLRU);       // JOINT strategy x perm (order 0)
        for (int pi = 1; pi < perms.Length; pi++)
            foreach (int m in strat)
                crossPerm.UnionWith(AllGreedy(o, pi, 0, false, m));

        var crossOrder = new HashSet<string>(modeLRU);      // JOINT strategy x order (perm 0)
        for (int qi = 1; qi < orders.Length; qi++)
            foreach (int m in strat)
                crossOrder.UnionWith(AllGreedy(o, 0, qi, false, m));

        var composite = new HashSet<string>(crossPerm);     // FULL strategy x perm x order
        composite.UnionWith(crossOrder);                    // = crossPerm U crossOrder U (both != 0)
        for (int pi = 1; pi < perms.Length; pi++)
            for (int qi = 1; qi < orders.Length; qi++)
                foreach (int m in strat)
                    composite.UnionWith(AllGreedy(o, pi, qi, false, m));

        PruneSamePlane = true;                              // SAME full composite, but no same-plane-consecutive
        var compositeP = new HashSet<string>(idSet);
        foreach (int m in strat) if (m != 0) compositeP.UnionWith(AllGreedy(o, 0, 0, false, m));
        for (int pi = 1; pi < perms.Length; pi++)
            foreach (int m in strat) compositeP.UnionWith(AllGreedy(o, pi, 0, false, m));
        for (int qi = 1; qi < orders.Length; qi++)
            foreach (int m in strat) compositeP.UnionWith(AllGreedy(o, 0, qi, false, m));
        for (int pi = 1; pi < perms.Length; pi++)
            for (int qi = 1; qi < orders.Length; qi++)
                foreach (int m in strat) compositeP.UnionWith(AllGreedy(o, pi, qi, false, m));
        PruneSamePlane = false;

        sumId += idSet.Count; sumModeLR += modeLRU.Count;
        sumCrossPerm += crossPerm.Count; sumCrossOrder += crossOrder.Count;
        sumComposite += composite.Count; sumCompositeP += compositeP.Count;

        foreach (var s in idSet) histId[Len(s)]++;
        foreach (var s in modeLRU)    if (!idSet.Contains(s)) histModeLR[Len(s)]++;
        foreach (var s in crossPerm)  if (!idSet.Contains(s)) histCrossPerm[Len(s)]++;
        foreach (var s in crossOrder) if (!idSet.Contains(s)) histCrossOrder[Len(s)]++;
        foreach (var s in composite)  if (!idSet.Contains(s)) histComposite[Len(s)]++;
    }

    int count = orientations.Count;
    var sb = new StringBuilder();
    sb.AppendLine($"Greedy decomposition diversity  (N = {n}, Size = {TRubikCube.Size})");
    sb.AppendLine($"  cubie orientations (rotation group) : {count}");
    sb.AppendLine($"  axis permutations (N!)              : {perms.Length}");
    sb.AppendLine($"  plane orders (of P! = {Factorial(TAffine.Planes.Length)}) : {orders.Length}");
    sb.AppendLine($"  reduction modes (2^P, pod/nad-L)    : {modeCount}");
    sb.AppendLine($"  reduction strategies (4^P, +L/R)    : {stratCount}");
    if (sampled)
        sb.AppendLine($"  *** SAMPLED: {count} orientations x {strat.Length} strategies x {orders.Length} orders (re-run for another draw) ***");
    sb.AppendLine();
    sb.AppendLine($"  baseline (standard QR)              : {sumId}   (avg {sumId / (double)count:0.00} / orientation)");
    sb.AppendLine();
    sb.AppendLine($"  strategy alone (4^P, perm0 order0)  : {sumModeLR}   (+{Pct(sumId, sumModeLR):0.0}%)");
    sb.AppendLine();
    sb.AppendLine("  JOINT cross (strategy x axis together) - synergy = gain OVER strategy alone:");
    sb.AppendLine($"  strategy x perm                     : {sumCrossPerm}   (+{Pct(sumId, sumCrossPerm):0.0}% vs base, +{Pct(sumModeLR, sumCrossPerm):0.0}% vs strategy)");
    sb.AppendLine($"  strategy x order                    : {sumCrossOrder}   (+{Pct(sumId, sumCrossOrder):0.0}% vs base, +{Pct(sumModeLR, sumCrossOrder):0.0}% vs strategy)");
    sb.AppendLine($"  strategy x perm x order (composite) : {sumComposite}   (+{Pct(sumId, sumComposite):0.0}% vs base, +{Pct(sumCrossPerm, sumComposite):0.0}% vs strat x perm)");
    sb.AppendLine($"  composite (NO same-plane)           : {sumCompositeP}   ({(sumComposite == sumCompositeP ? "SAME -> pruning LOSSLESS on composite (thesis holds!)" : $"lost {sumComposite - sumCompositeP} -> still loses")})");
    sb.AppendLine();
    sb.AppendLine("  manoeuvres by length  (baseline count, then EXTRA vs baseline):");
    sb.AppendLine("    length  baseline   strat  xPerm  xOrder  compos");
    for (int L = 0; L < histId.Length; L++)
        if (histId[L] > 0 || histModeLR[L] > 0 || histCrossPerm[L] > 0 || histCrossOrder[L] > 0 || histComposite[L] > 0)
            sb.AppendLine($"    {L,6}  {histId[L],8}  {histModeLR[L],6}  {histCrossPerm[L],6}  {histCrossOrder[L],7}  {histComposite[L],6}");
    return sb.ToString();
}

