// Moves-to-solve of an orientation under (perm, mixed-Givens mode): first conjugate by the axis
// permutation (A = PᵀMP), then reduce plane-by-plane in natural order with a per-plane strategy packed
// 2 bits per plane in modeMask (base-4): 0=pod-L, 1=nad-L, 2=pod-R, 3=nad-R. pod/nad zero the SUB- vs
// SUPER-diagonal; L/R = row op (left, Rotate, -sin) vs column op (right, RotatePost, +sin) - a right op
// still yields a real cube move (L*M*R = I => M^-1 = R*L). Identity perm + modeMask 0 = standard QR
// baseline. Non-destructive (builds the permuted copy). Mirrors the effect-verified TGreedyDiversity.RotCount.
static int RotCountMode(TMatrix M, int[] perm, int modeMask)
{
    int n = TAffine.N;
    var A = new TMatrix(n, n);                          // permuted copy: A[y,x] = M[perm[y], perm[x]]
    for (int y = 0; y < n; y++)
        for (int x = 0; x < n; x++)
            A[y, x] = M[perm[y], perm[x]];
    int c = 0;
    for (int p = 0; p < TAffine.Planes.Length; p++)
    {
        int a1 = TAffine.Planes[p][0], a2 = TAffine.Planes[p][1];
        int strat = (modeMask >> (2 * p)) & 3;         // 0=pod-L 1=nad-L 2=pod-R 3=nad-R
        float a, b;
        switch (strat)
        {
            case 0:  a = A[a1, a1]; b =  A[a2, a1]; break;   // pod-L: zero sub-diag [a2,a1] (row op)
            case 1:  a = A[a2, a2]; b = -A[a1, a2]; break;   // nad-L: zero super-diag [a1,a2] (row op)
            case 2:  a = A[a2, a2]; b = -A[a2, a1]; break;   // pod-R: zero sub-diag [a2,a1] (col op)
            default: a = A[a1, a1]; b =  A[a1, a2]; break;   // nad-R: zero super-diag [a1,a2] (col op)
        }
        float r = (float)Math.Sqrt(a * a + b * b);
        if (r < 0.1f) continue;                                            // pivot ~ 0 -> identity rotation
        float cos = a / r, sin = b / r;
        if (strat < 2) A.Rotate(a1, a2, cos, -sin);        // left: row op, -sin
        else           A.RotatePost(a1, a2, cos, sin);     // right: col op, +sin
        if (TCubie.GetAngle(cos, sin) != 0) c++;
    }
    return c;
}

// mode moves-to-solve of orientation M after applying cube move (plane, angle). Clones the small n x n
// matrix (not the whole cubie) and left-rotates it exactly as Turn rotates a cubie, so the greedy's
// prediction matches the real move; the clone leaves M intact for the sibling candidates.
static int RotCountModeAfter(TMatrix M, int plane, int angle, int[] perm, int modeMask)
{
    var A = (TMatrix)M.Clone();
    var pa = TAffine.Planes[plane];
    var rot = TCubie.SetAngle(angle);
    A.Rotate(pa[0], pa[1], rot.X, rot.Y);
    return RotCountMode(A, perm, modeMask);
}

static int[] IdentityPerm()
{
    var p = new int[TAffine.N];
    for (int i = 0; i < TAffine.N; i++) p[i] = i;
    return p;
}

// A random axis permutation (every permutation is a valid metric conjugation PᵀMP). Drawn per seed so
// the seed pool samples the strategy x perm space - the biggest diversity synergy the diagnostic found.
static int[] RandomPerm()
{
    var p = IdentityPerm();
    for (int i = p.Length - 1; i > 0; i--)
    {
        int j = TChromosome.Rnd.Next(i + 1);
        (p[i], p[j]) = (p[j], p[i]);
    }
    return p;
}

