// A random axis permutation (every permutation is a valid metric conjugation PᵀMP). Drawn per seed so
// the seed pool samples the strategy x perm space - the biggest diversity synergy the diagnostic found.
static int[] RandomPerm()
{
    var p = IdentityPerm();
    for (int i = p.Length - 1; i > 0; i--)
    {
        int j = TChromosome.Rnd.Next(i + 1);
        (p[i], p[j]) = (p[j], p[i]);
    }
    return p;
}

