static int[] RandomOrder()
{
    var o = IdentityOrder();
    for (int i = o.Length - 1; i > 0; i--)
    {
        int j = TChromosome.Rnd.Next(i + 1);
        (o[i], o[j]) = (o[j], o[i]);
    }
    return o;
}

