1	#version 430
2	#include "Setup.glsl.c"
3	
4	// 1 thread = 1 specimen. A block of 64 threads processes 64 specimens at once.
5	layout(local_size_x = 64) in;
6	
7	void main()
8	{
9	    uint specimenID = gl_GlobalInvocationID.x;
10	    if (specimenID >= Population.length()) return;
11	
12	    float maxClusterState = float(MAX_CUBIE_STATE) * float(countActive);
13	    float max_fA = maxClusterState * (float(countActive) + 1.0);
14	
15	    // Per-thread (per-specimen) records initialized to the maximum float value
16	    float specimen_best_fitness = 1e38;
17	    uint specimen_best_moves_count = 0;
18	
19	    // CUBE IN REGISTERS: thread-private array mapped to ultra-fast ALU registers.
20	    // Cubies holds the shared read-only starting state; each thread copies it into its private
21	    // working array and mutates only that copy, so the single shared buffer is race-free.
22	    uint local_cubies[CUBIES_COUNT];
23	    for (uint i = 0; i < CUBIES_COUNT; i++)
24	        local_cubies[i] = Cubies[i];
25	
26	    for (int m = 0; m < GENES_COUNT; m++)
27	    {
28	        Move move = getMove(Population[specimenID].Moves[m]);
29	
30	        // 2a. CUBE ROTATION: the thread modifies only its own private registers
31	        for (uint cubieID = 0; cubieID < CUBIES_COUNT; cubieID++)
32	            local_cubies[cubieID] = TurnSingleCubie(local_cubies[cubieID], cubieID, move);
33	
34	        // 2b. SEQUENTIAL EVALUATION: the thread sums its own errors for the current step 'm'
35	        float local_fA_sum = 0.0;
36	        uint scrambled = 0u;
37	        uint local_solved_errors = 0;
38	        bool changed = false;
39	        for (uint i = 0; i < countActive; i++) {
40	            uint cur = local_cubies[ActiveCubies[i]];
41	            if (cur != Cubies[ActiveCubies[i]]) changed = true;   // did this prefix move the active cluster?
42	            float e = GetActiveCubieError(cur, maxClusterState, max_fA);
43	            local_fA_sum += e;
44	            if (e != 0.0) scrambled++;
45	        }
46	        // Endgame: once <= N active cubies remain unsolved, stop rewarding fewer of them (fewer is
47	        // not easier - a lone twisted cubie / mono-twist is very hard to escape). Amplify by
48	        // N/scrambled so the search then optimises the orientation magnitude, not the count.
49	        //if (scrambled > 0u && scrambled <= uint(N))
50	        //    local_fA_sum *= float(N) / float(scrambled);
51	        for (uint i = 0; i < countSolved; i++)
52	            if (cubieL1(local_cubies[SolvedCubies[i]]) != 0u)
53	                local_solved_errors += 1;
54	        float current_step_fitness = float(local_solved_errors) + local_fA_sum;
55	        if (!changed) current_step_fitness += float(2 * CUBIES_COUNT);   // no-op on the active cluster: rank below every real move (max real fitness <= CUBIES_COUNT, since solved+active = CUBIES_COUNT and the active term <= 1)
56	        if (current_step_fitness < specimen_best_fitness) {
57	            specimen_best_fitness = current_step_fitness;
58	            specimen_best_moves_count = uint(m + 1);
59	        }
60	    }
61	
62	    // 3: Write the record back to the population
63	    Population[specimenID].Fitness = floatBitsToUint(specimen_best_fitness);
64	    Population[specimenID].MovesCount = specimen_best_moves_count;
65	}
