315	        // moves) and returns its fitness = the cube's raw score PLUS the no-op penalty (a zero specimen
316	        // never changes the active cluster, so the penalty always fires).
317	        static float EvalZeroSpecimen(TRubikCube cube)
318	        {
319	            CreateBuffers(cube);
320	            var micro = cube.Cubies.Length <= 64;
321	            var eval = micro ? EvaluateMicroProgram : EvaluateMacroProgram;
322	            var spec = new int[TChromosome.GenesLength + 2];   // all zero = identity moves
323	            fixed (int* p = spec) Population.Update(spec.Length * sizeof(int), p);
324	            OpenGL.UseProgram(eval);
325	            OpenGL.Uniform1ui(4, (uint)cube.SolvedCubies.Count);
326	            OpenGL.Uniform1ui(5, (uint)cube.ActiveCluster.Count);
327	            OpenGL.BindBufferBase(Population.Type, 0, Population.Id);
328	            OpenGL.DispatchCompute(1, 1, 1);                        // one specimen: 1 thread (micro) / 1 block (macro)
329	            OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
330	            var result = new int[1];
331	            OpenGL.BindBuffer(Population.Type, Population.Id);
332	            fixed (int* rp = result)
333	                OpenGL.GetBufferSubData(Population.Type, 0, sizeof(float), rp);
334	            return BitConverter.Int32BitsToSingle(result[0]);
335	        }
