                uint ida = ActiveCubies[a];
                uint sa = local_cubies[ida];
                if (sa == Cubies[ida]) continue;              // group only scrambled cubies
                uint ca[N];
                for (uint j = 0u; j < uint(N); j++) ca[j] = curCoord(sa, ida, j);
                uint cnt[PLANES_COUNT];                        // one bin per axis PAIR (two-layer intersection)
                for (uint p = 0u; p < uint(PLANES_COUNT); p++) cnt[p] = 1u;   // 'a' itself in every pair-group
                for (uint b = a + 1u; b < countActive; b++) {
                    uint idb = ActiveCubies[b];
                    uint sb = local_cubies[idb];
                    if (sb != sa) continue;                   // different orientation -> not co-collapsible
                    uint cb[N];
                    for (uint j = 0u; j < uint(N); j++) cb[j] = curCoord(sb, idb, j);
                    // Count b into every axis pair (j1,j2) it shares with a - i.e. every two-layer
                    // intersection they co-occupy. Pair index runs 0..PLANES_COUNT-1, same enumeration
                    // as the rotation planes (both are the C(N,2) axis pairs).
                    uint p = 0u;
                    for (uint j1 = 0u; j1 < uint(N); j1++)
                        for (uint j2 = j1 + 1u; j2 < uint(N); j2++) {
                            if (ca[j1] == cb[j1] && ca[j2] == cb[j2]) cnt[p]++;
                            p++;
                        }
                }
                for (uint p = 0u; p < uint(PLANES_COUNT); p++)
                    if (cnt[p] > maxHist) maxHist = cnt[p];
            }
            // Refund ONLY a COMPLETE clean unit: the WHOLE residual is one same-state intersection
            // (maxHist == scrambled) of power-of-2 size (the signature of a full 2^(N-f) intersection -
            // a coincidental partial gathering of 5/6/7 is not a power of 2). Rewarding PARTIAL coherence
            // (maxHist < scrambled) is what created the mid-game plateau: a coincidental group scored like
            // a more-solved state and flattened the homing gradient. This gate fires the discount ONLY at
            // genuinely near-solved states, so it cannot plateau - if it never matches, the term is exactly
            // baseline (downside-protected).
            if (maxHist == scrambled && (scrambled & (scrambled - 1u)) == 0u)
                local_fA_sum -= float(maxHist - 1u) * (maxClusterState / max_fA);   // one cubie-unit = maxClusterState/max_fA
        }
#endif
        // Endgame: once <= N active cubies remain unsolved, stop rewarding fewer of them (fewer is
        // not easier - a lone twisted cubie / mono-twist is very hard to escape). Amplify by
        // N/scrambled so the search then optimises the orientation magnitude, not the count.
        //if (scrambled > 0u && scrambled <= uint(N))
        //    local_fA_sum *= float(N) / float(scrambled);
        for (uint i = 0; i < countSolved; i++)
            if (cubieL1(local_cubies[SolvedCubies[i]]) != 0u)
                local_solved_errors += 1;
        float current_step_fitness = float(local_solved_errors) + local_fA_sum;
        if (!changed) current_step_fitness += float(2 * CUBIES_COUNT);   // no-op on the active cluster: rank below every real move (max real fitness <= CUBIES_COUNT, since solved+active = CUBIES_COUNT and the active term <= 1)
        if (current_step_fitness < specimen_best_fitness) {
            specimen_best_fitness = current_step_fitness;
            specimen_best_moves_count = uint(m + 1);
        }
    }

    // 3: Write the record back to the population
    Population[specimenID].Fitness = floatBitsToUint(specimen_best_fitness);
    Population[specimenID].MovesCount = specimen_best_moves_count;
}
